INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(9, '1 Sam', '1 Samuel', 1, 1, 'There was a certain man of Ramathaim, a Zuphite from the hill country of Ephraim, whose name was Elkanah son of Jeroham son of Elihu son of Tohu son of Zuph, an Ephraimite.', 'en', 'NRSV-CE', 'Samuel"s Birth and Dedication'),
(9, '1 Sam', '1 Samuel', 1, 2, 'He had two wives; the name of the one was Hannah, and the name of the other Peninnah. Peninnah had children, but Hannah had no children.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 1, 3, 'Now this man used to go up year by year from his town to worship and to sacrifice to the LORD of hosts at Shiloh, where the two sons of Eli, Hophni and Phinehas, were priests of the LORD.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 1, 4, 'On the day when Elkanah sacrificed, he would give portions to his wife Peninnah and to all her sons and daughters;', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 1, 5, 'but to Hannah he gave a double portion, because he loved her, though the LORD had closed her womb.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 1, 6, 'Her rival used to provoke her severely, to irritate her, because the LORD had closed her womb.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 1, 7, 'So it went on year by year; as often as she went up to the house of the LORD, she used to provoke her. Therefore Hannah wept and would not eat.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 1, 8, 'Her husband Elkanah said to her, "Hannah, why do you weep? Why do you not eat? Why is your heart sad? Am I not more to you than ten sons?"', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 1, 9, 'After they had eaten and drunk at Shiloh, Hannah rose and presented herself before the LORD. Now Eli the priest was sitting on the seat beside the doorpost of the temple of the LORD.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 1, 10, 'She was deeply distressed and prayed to the LORD, and wept bitterly.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 1, 11, 'She made this vow: "O LORD of hosts, if only you will look on the misery of your servant, and remember me, and not forget your servant, but will give to your servant a male child, then I will set him before you as a nazirite until the day of his death. He shall drink neither wine nor intoxicants, and no razor shall touch his head."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 1, 12, 'As she continued praying before the LORD, Eli observed her mouth.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 1, 13, 'Hannah was praying silently; only her lips moved, but her voice was not heard; therefore Eli thought she was drunk.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 1, 14, 'So Eli said to her, "How long will you make a drunken spectacle of yourself? Put away your wine."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 1, 15, 'But Hannah answered, "No, my lord, I am a woman deeply troubled; I have drunk neither wine nor strong drink, but I have been pouring out my soul before the LORD.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 1, 16, 'Do not regard your servant as a worthless woman, for I have been speaking out of my great anxiety and vexation all this time."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 1, 17, 'Then Eli answered, "Go in peace; the God of Israel grant the petition you have made to him."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 1, 18, 'And she said, "Let your servant find favor in your sight." Then the woman went to her quarters, ate and drank with her husband, and her countenance was sad no longer.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 1, 19, 'They rose early in the morning and worshiped before the LORD; then they went back to their house at Ramah. Elkanah knew his wife Hannah, and the LORD remembered her.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 1, 20, 'In due time Hannah conceived and bore a son. She named him Samuel, for she said, "I have asked him of the LORD."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 1, 21, 'The man Elkanah and all his household went up to offer to the LORD the yearly sacrifice, and to pay his vow.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 1, 22, 'But Hannah did not go up, for she said to her husband, "As soon as the child is weaned, I will bring him, that he may appear in the presence of the LORD, and remain there forever; I will offer him as a nazirite for all time."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 1, 23, 'Her husband Elkanah said to her, "Do what seems best to you, wait until you have weaned him; only--may the LORD establish his word." So the woman remained and nursed her son, until she weaned him.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 1, 24, 'When she had weaned him, she took him up with her, along with a three-year-old bull, an ephah of flour, and a skin of wine. She brought him to the house of the LORD at Shiloh; and the child was young.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 1, 25, 'Then they slaughtered the bull, and they brought the child to Eli.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 1, 26, 'And she said, "Oh, my lord! As you live, my lord, I am the woman who was standing here in your presence, praying to the LORD.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 1, 27, 'For this child I prayed; and the LORD has granted me the petition that I made to him.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 1, 28, 'Therefore I have lent him to the LORD; as long as he lives, he is given to the LORD."
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(9, '1 Sam', '1 Samuel', 2, 1, 'Hannah prayed and said,
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(9, '1 Sam', '1 Samuel', 3, 1, 'Now the boy Samuel was ministering to the LORD under Eli. The word of the LORD was rare in those days; visions were not widespread.', 'en', 'NRSV-CE', 'Samuel"s Calling and Prophetic Activity'),
(9, '1 Sam', '1 Samuel', 3, 2, 'At that time Eli, whose eyesight had begun to grow dim so that he could not see, was lying down in his room;', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 3, 3, 'the lamp of God had not yet gone out, and Samuel was lying down in the temple of the LORD, where the ark of God was.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 3, 4, 'Then the LORD called, "Samuel! Samuel!" and he said, "Here I am!"', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 3, 5, 'and ran to Eli, and said, "Here I am, for you called me." But he said, "I did not call; lie down again." So he went and lay down.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 3, 6, 'The LORD called again, "Samuel!" Samuel got up and went to Eli, and said, "Here I am, for you called me." But he said, "I did not call, my son; lie down again."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 3, 7, 'Now Samuel did not yet know the LORD, and the word of the LORD had not yet been revealed to him.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 3, 8, 'The LORD called Samuel again, a third time. And he got up and went to Eli, and said, "Here I am, for you called me." Then Eli perceived that the LORD was calling the boy.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 3, 9, 'Therefore Eli said to Samuel, "Go, lie down; and if he calls you, you shall say, "Speak, LORD, for your servant is listening."" So Samuel went and lay down in his place.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 3, 10, 'Now the LORD came and stood there, calling as before, "Samuel! Samuel!" And Samuel said, "Speak, for your servant is listening."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 3, 11, 'Then the LORD said to Samuel, "See, I am about to do something in Israel that will make both ears of anyone who hears of it tingle.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 3, 12, 'On that day I will fulfill against Eli all that I have spoken concerning his house, from beginning to end.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 3, 13, 'For I have told him that I am about to punish his house forever, for the iniquity that he knew, because his sons were blaspheming God, and he did not restrain them.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 3, 14, 'Therefore I swear to the house of Eli that the iniquity of Eli"s house shall not be expiated by sacrifice or offering forever."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 3, 15, 'Samuel lay there until morning; then he opened the doors of the house of the LORD. Samuel was afraid to tell the vision to Eli.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 3, 16, 'But Eli called Samuel and said, "Samuel, my son." He said, "Here I am."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 3, 17, 'Eli said, "What was it that he told you? Do not hide it from me. May God do so to you and more also, if you hide anything from me of all that he told you."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 3, 18, 'So Samuel told him everything and hid nothing from him. Then he said, "It is the LORD; let him do what seems good to him."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 3, 19, 'As Samuel grew up, the LORD was with him and let none of his words fall to the ground.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 3, 20, 'And all Israel from Dan to Beer-sheba knew that Samuel was a trustworthy prophet of the LORD.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 3, 21, 'The LORD continued to appear at Shiloh, for the LORD revealed himself to Samuel at Shiloh by the word of the LORD.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(9, '1 Sam', '1 Samuel', 4, 1, 'And the word of Samuel came to all Israel.
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(9, '1 Sam', '1 Samuel', 5, 1, 'When the Philistines captured the ark of God, they brought it from Ebenezer to Ashdod;', 'en', 'NRSV-CE', 'The Philistines and the Ark'),
(9, '1 Sam', '1 Samuel', 5, 2, 'then the Philistines took the ark of God and brought it into the house of Dagon and placed it beside Dagon.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 5, 3, 'When the people of Ashdod rose early the next day, there was Dagon, fallen on his face to the ground before the ark of the LORD. So they took Dagon and put him back in his place.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 5, 4, 'But when they rose early on the next morning, Dagon had fallen on his face to the ground before the ark of the LORD, and the head of Dagon and both his hands were lying cut off upon the threshold; only the trunk of Dagon was left to him.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 5, 5, 'This is why the priests of Dagon and all who enter the house of Dagon do not step on the threshold of Dagon in Ashdod to this day.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 5, 6, 'The hand of the LORD was heavy upon the people of Ashdod, and he terrified and struck them with tumors, both in Ashdod and in its territory.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 5, 7, 'And when the inhabitants of Ashdod saw how things were, they said, "The ark of the God of Israel must not remain with us; for his hand is heavy on us and on our god Dagon."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 5, 8, 'So they sent and gathered together all the lords of the Philistines, and said, "What shall we do with the ark of the God of Israel?" The inhabitants of Gath replied, "Let the ark of God be moved on to us." So they moved the ark of the God of Israel to Gath.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 5, 9, 'But after they had brought it to Gath, the hand of the LORD was against the city, causing a very great panic; he struck the inhabitants of the city, both young and old, so that tumors broke out on them.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 5, 10, 'So they sent the ark of the God of Israel to Ekron. But when the ark of God came to Ekron, the people of Ekron cried out, "Why have they brought around to us the ark of the God of Israel to kill us and our people?"', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 5, 11, 'They sent therefore and gathered together all the lords of the Philistines, and said, "Send away the ark of the God of Israel, and let it return to its own place, that it may not kill us and our people." For there was a deathly panic throughout the whole city. The hand of God was very heavy there;', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 5, 12, 'those who did not die were stricken with tumors, and the cry of the city went up to heaven.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(9, '1 Sam', '1 Samuel', 6, 1, 'The ark of the LORD was in the country of the Philistines seven months.', 'en', 'NRSV-CE', 'The Ark Returned to Israel'),
(9, '1 Sam', '1 Samuel', 6, 2, 'Then the Philistines called for the priests and the diviners and said, "What shall we do with the ark of the LORD? Tell us what we should send with it to its place."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 6, 3, 'They said, "If you send away the ark of the God of Israel, do not send it empty, but by all means return him a guilt offering. Then you will be healed and will be ransomed; will not his hand then turn from you?"', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 6, 4, 'And they said, "What is the guilt offering that we shall return to him?" They answered, "Five gold tumors and five gold mice, according to the number of the lords of the Philistines; for the same plague was upon all of you and upon your lords.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 6, 5, 'So you must make images of your tumors and images of your mice that ravage the land, and give glory to the God of Israel; perhaps he will lighten his hand on you and your gods and your land.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 6, 6, 'Why should you harden your hearts as the Egyptians and Pharaoh hardened their hearts? After he had made fools of them, did they not let the people go, and they departed?', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 6, 7, 'Now then, get ready a new cart and two milch cows that have never borne a yoke, and yoke the cows to the cart, but take their calves home, away from them.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 6, 8, 'Take the ark of the LORD and place it on the cart, and put in a box at its side the figures of gold, which you are returning to him as a guilt offering. Then send it off, and let it go its way.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 6, 9, 'And watch; if it goes up on the way to its own land, to Beth-shemesh, then it is he who has done us this great harm; but if not, then we shall know that it is not his hand that struck us; it happened to us by chance."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 6, 10, 'The men did so; they took two milch cows and yoked them to the cart, and shut up their calves at home.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 6, 11, 'They put the ark of the LORD on the cart, and the box with the gold mice and the images of their tumors.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 6, 12, 'The cows went straight in the direction of Beth-shemesh along one highway, lowing as they went; they turned neither to the right nor to the left, and the lords of the Philistines went after them as far as the border of Beth-shemesh.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 6, 13, 'Now the people of Beth-shemesh were reaping their wheat harvest in the valley. When they looked up and saw the ark, they went with rejoicing to meet it.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 6, 14, 'The cart came into the field of Joshua of Beth-shemesh, and stopped there. A large stone was there; so they split up the wood of the cart and offered the cows as a burnt offering to the LORD.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 6, 15, 'The Levites took down the ark of the LORD and the box that was beside it, in which were the gold objects, and set them upon the large stone. Then the people of Beth-shemesh offered burnt offerings and presented sacrifices on that day to the LORD.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 6, 16, 'When the five lords of the Philistines saw it, they returned that day to Ekron.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 6, 17, 'These are the gold tumors, which the Philistines returned as a guilt offering to the LORD: one for Ashdod, one for Gaza, one for Ashkelon, one for Gath, one for Ekron;', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 6, 18, 'also the gold mice, according to the number of all the cities of the Philistines belonging to the five lords, both fortified cities and unwalled villages. The great stone, beside which they set down the ark of the LORD, is a witness to this day in the field of Joshua of Beth-shemesh.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 6, 19, 'The descendants of Jeconiah did not rejoice with the people of Beth-shemesh when they greeted the ark of the LORD; and he killed seventy men of them. The people mourned because the LORD had made a great slaughter among the people.', 'en', 'NRSV-CE', 'The Ark at Kiriath-jearim'),
(9, '1 Sam', '1 Samuel', 6, 20, 'Then the people of Beth-shemesh said, "Who is able to stand before the LORD, this holy God? To whom shall he go so that we may be rid of him?"', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 6, 21, 'So they sent messengers to the inhabitants of Kiriath-jearim, saying, "The Philistines have returned the ark of the LORD. Come down and take it up to you."', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(9, '1 Sam', '1 Samuel', 7, 1, 'And the people of Kiriath-jearim came and took up the ark of the LORD, and brought it to the house of Abinadab on the hill. They consecrated his son, Eleazar, to have charge of the ark of the LORD.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 7, 2, 'From the day that the ark was lodged at Kiriath-jearim, a long time passed, some twenty years, and all the house of Israel lamented after the LORD.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 7, 3, 'Then Samuel said to all the house of Israel, "If you are returning to the LORD with all your heart, then put away the foreign gods and the Astartes from among you. Direct your heart to the LORD, and serve him only, and he will deliver you out of the hand of the Philistines."', 'en', 'NRSV-CE', 'Samuel as Judge'),
(9, '1 Sam', '1 Samuel', 7, 4, 'So Israel put away the Baals and the Astartes, and they served the LORD only.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 7, 5, 'Then Samuel said, "Gather all Israel at Mizpah, and I will pray to the LORD for you."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 7, 6, 'So they gathered at Mizpah, and drew water and poured it out before the LORD. They fasted that day, and said, "We have sinned against the LORD." And Samuel judged the people of Israel at Mizpah.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 7, 7, 'When the Philistines heard that the people of Israel had gathered at Mizpah, the lords of the Philistines went up against Israel. And when the people of Israel heard of it they were afraid of the Philistines.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 7, 8, 'The people of Israel said to Samuel, "Do not cease to cry out to the LORD our God for us, and pray that he may save us from the hand of the Philistines."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 7, 9, 'So Samuel took a sucking lamb and offered it as a whole burnt offering to the LORD; Samuel cried out to the LORD for Israel, and the LORD answered him.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 7, 10, 'As Samuel was offering up the burnt offering, the Philistines drew near to attack Israel; but the LORD thundered with a mighty voice that day against the Philistines and threw them into confusion; and they were routed before Israel.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 7, 11, 'And the men of Israel went out of Mizpah and pursued the Philistines, and struck them down as far as beyond Beth-car.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 7, 12, 'Then Samuel took a stone and set it up between Mizpah and Jeshanah, and named it Ebenezer; for he said, "Thus far the LORD has helped us."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 7, 13, 'So the Philistines were subdued and did not again enter the territory of Israel; the hand of the LORD was against the Philistines all the days of Samuel.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 7, 14, 'The towns that the Philistines had taken from Israel were restored to Israel, from Ekron to Gath; and Israel recovered their territory from the hand of the Philistines. There was peace also between Israel and the Amorites.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 7, 15, 'Samuel judged Israel all the days of his life.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 7, 16, 'He went on a circuit year by year to Bethel, Gilgal, and Mizpah; and he judged Israel in all these places.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 7, 17, 'Then he would come back to Ramah, for his home was there; he administered justice there to Israel, and built there an altar to the LORD.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(9, '1 Sam', '1 Samuel', 8, 1, 'When Samuel became old, he made his sons judges over Israel.', 'en', 'NRSV-CE', 'Israel Demands a King'),
(9, '1 Sam', '1 Samuel', 8, 2, 'The name of his firstborn son was Joel, and the name of his second, Abijah; they were judges in Beer-sheba.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 8, 3, 'Yet his sons did not follow in his ways, but turned aside after gain; they took bribes and perverted justice.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 8, 4, 'Then all the elders of Israel gathered together and came to Samuel at Ramah,', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 8, 5, 'and said to him, "You are old and your sons do not follow in your ways; appoint for us, then, a king to govern us, like other nations."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 8, 6, 'But the thing displeased Samuel when they said, "Give us a king to govern us." Samuel prayed to the LORD,', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 8, 7, 'and the LORD said to Samuel, "Listen to the voice of the people in all that they say to you; for they have not rejected you, but they have rejected me from being king over them.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 8, 8, 'Just as they have done to me, from the day I brought them up out of Egypt to this day, forsaking me and serving other gods, so also they are doing to you.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 8, 9, 'Now then, listen to their voice; only--you shall solemnly warn them, and show them the ways of the king who shall reign over them."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 8, 10, 'So Samuel reported all the words of the LORD to the people who were asking him for a king.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 8, 11, 'He said, "These will be the ways of the king who will reign over you: he will take your sons and appoint them to his chariots and to be his horsemen, and to run before his chariots;', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 8, 12, 'and he will appoint for himself commanders of thousands and commanders of fifties, and some to plow his ground and to reap his harvest, and to make his implements of war and the equipment of his chariots.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 8, 13, 'He will take your daughters to be perfumers and cooks and bakers.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 8, 14, 'He will take the best of your fields and vineyards and olive orchards and give them to his courtiers.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 8, 15, 'He will take one-tenth of your grain and of your vineyards and give it to his officers and his courtiers.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 8, 16, 'He will take your male and female slaves, and the best of your cattle and donkeys, and put them to his work.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 8, 17, 'He will take one-tenth of your flocks, and you shall be his slaves.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 8, 18, 'And in that day you will cry out because of your king, whom you have chosen for yourselves; but the LORD will not answer you in that day."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 8, 19, 'But the people refused to listen to the voice of Samuel; they said, "No! but we are determined to have a king over us,', 'en', 'NRSV-CE', 'Israel"s Request for a King Granted'),
(9, '1 Sam', '1 Samuel', 8, 20, 'so that we also may be like other nations, and that our king may govern us and go out before us and fight our battles."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 8, 21, 'When Samuel had heard all the words of the people, he repeated them in the ears of the LORD.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 8, 22, 'The LORD said to Samuel, "Listen to their voice and set a king over them." Samuel then said to the people of Israel, "Each of you return home."', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(9, '1 Sam', '1 Samuel', 9, 1, 'There was a man of Benjamin whose name was Kish son of Abiel son of Zeror son of Becorath son of Aphiah, a Benjaminite, a man of wealth.', 'en', 'NRSV-CE', 'Saul Chosen to Be King'),
(9, '1 Sam', '1 Samuel', 9, 2, 'He had a son whose name was Saul, a handsome young man. There was not a man among the people of Israel more handsome than he; he stood head and shoulders above everyone else.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 9, 3, 'Now the donkeys of Kish, Saul"s father, had strayed. So Kish said to his son Saul, "Take one of the boys with you; go and look for the donkeys."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 9, 4, 'He passed through the hill country of Ephraim and passed through the land of Shalishah, but they did not find them. And they passed through the land of Shaalim, but they were not there. Then he passed through the land of Benjamin, but they did not find them.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 9, 5, 'When they came to the land of Zuph, Saul said to the boy who was with him, "Let us turn back, or my father will stop worrying about the donkeys and worry about us."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 9, 6, 'But he said to him, "There is a man of God in this town; he is a man held in honor. Whatever he says always comes true. Let us go there now; perhaps he will tell us about the journey on which we have set out."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 9, 7, 'Then Saul replied to the boy, "But if we go, what can we bring the man? For the bread in our sacks is gone, and there is no present to bring to the man of God. What have we?"', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 9, 8, 'The boy answered Saul again, "Here, I have with me a quarter shekel of silver; I will give it to the man of God, to tell us our way."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 9, 9, '(Formerly in Israel, anyone who went to inquire of God would say, "Come, let us go to the seer"; for the one who is now called a prophet was formerly called a seer.)', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 9, 10, 'Saul said to the boy, "Good; come, let us go." So they went to the town where the man of God was.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 9, 11, 'As they went up the hill to the town, they met some girls coming out to draw water, and said to them, "Is the seer here?"', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 9, 12, 'They answered, "Yes, there he is just ahead of you. Hurry; he has come just now to the town, because the people have a sacrifice today at the shrine.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 9, 13, 'As soon as you enter the town, you will find him, before he goes up to the shrine to eat. For the people will not eat until he comes, since he must bless the sacrifice; afterward those eat who are invited. Now go up, for you will meet him immediately."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 9, 14, 'So they went up to the town. As they were entering the town, they saw Samuel coming out toward them on his way up to the shrine.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 9, 15, 'Now the day before Saul came, the LORD had revealed to Samuel:', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 9, 16, '"Tomorrow about this time I will send to you a man from the land of Benjamin, and you shall anoint him to be ruler over my people Israel. He shall save my people from the hand of the Philistines; for I have seen the suffering of my people, because their outcry has come to me."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 9, 17, 'When Samuel saw Saul, the LORD told him, "Here is the man of whom I spoke to you. He it is who shall rule over my people."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 9, 18, 'Then Saul approached Samuel inside the gate, and said, "Tell me, please, where is the house of the seer?"', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 9, 19, 'Samuel answered Saul, "I am the seer; go up before me to the shrine, for today you shall eat with me, and in the morning I will let you go and will tell you all that is on your mind.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 9, 20, 'As for your donkeys that were lost three days ago, give no further thought to them, for they have been found. And on whom is all Israel"s desire fixed, if not on you and on all your ancestral house?"', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 9, 21, 'Saul answered, "I am only a Benjaminite, from the least of the tribes of Israel, and my family is the humblest of all the families of the tribe of Benjamin. Why then have you spoken to me in this way?"', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 9, 22, 'Then Samuel took Saul and his servant-boy and brought them into the hall, and gave them a place at the head of those who had been invited, of whom there were about thirty.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 9, 23, 'And Samuel said to the cook, "Bring the portion I gave you, the one I asked you to put aside."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 9, 24, 'The cook took up the thigh and what went with it and set them before Saul. Samuel said, "See, what was kept is set before you. Eat; for it is set before you at the appointed time, so that you might eat with the guests."
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(9, '1 Sam', '1 Samuel', 10, 1, 'Samuel took a vial of oil and poured it on his head, and kissed him; he said, "The LORD has anointed you ruler over his people Israel. You shall reign over the people of the LORD and you will save them from the hand of their enemies all around. Now this shall be the sign to you that the LORD has anointed you ruler over his heritage:', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 10, 2, 'When you depart from me today you will meet two men by Rachel"s tomb in the territory of Benjamin at Zelzah; they will say to you, "The donkeys that you went to seek are found, and now your father has stopped worrying about them and is worrying about you, saying: What shall I do about my son?"', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 10, 3, 'Then you shall go on from there further and come to the oak of Tabor; three men going up to God at Bethel will meet you there, one carrying three kids, another carrying three loaves of bread, and another carrying a skin of wine.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 10, 4, 'They will greet you and give you two loaves of bread, which you shall accept from them.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 10, 5, 'After that you shall come to Gibeath-elohim, at the place where the Philistine garrison is; there, as you come to the town, you will meet a band of prophets coming down from the shrine with harp, tambourine, flute, and lyre playing in front of them; they will be in a prophetic frenzy.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 10, 6, 'Then the spirit of the LORD will possess you, and you will be in a prophetic frenzy along with them and be turned into a different person.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 10, 7, 'Now when these signs meet you, do whatever you see fit to do, for God is with you.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 10, 8, 'And you shall go down to Gilgal ahead of me; then I will come down to you to present burnt offerings and offer sacrifices of well-being. Seven days you shall wait, until I come to you and show you what you shall do."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 10, 9, 'As he turned away to leave Samuel, God gave him another heart; and all these signs were fulfilled that day.', 'en', 'NRSV-CE', 'Saul Prophesies'),
(9, '1 Sam', '1 Samuel', 10, 10, 'When they were going from there to Gibeah, a band of prophets met him; and the spirit of God possessed him, and he fell into a prophetic frenzy along with them.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 10, 11, 'When all who knew him before saw how he prophesied with the prophets, the people said to one another, "What has come over the son of Kish? Is Saul also among the prophets?"', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 10, 12, 'A man of the place answered, "And who is their father?" Therefore it became a proverb, "Is Saul also among the prophets?"', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 10, 13, 'When his prophetic frenzy had ended, he went home.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 10, 14, 'Saul"s uncle said to him and to the boy, "Where did you go?" And he replied, "To seek the donkeys; and when we saw they were not to be found, we went to Samuel."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 10, 15, 'Saul"s uncle said, "Tell me what Samuel said to you."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 10, 16, 'Saul said to his uncle, "He told us that the donkeys had been found." But about the matter of the kingship, of which Samuel had spoken, he did not tell him anything.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 10, 17, 'Samuel summoned the people to the LORD at Mizpah', 'en', 'NRSV-CE', 'Saul Proclaimed King'),
(9, '1 Sam', '1 Samuel', 10, 18, 'and said to them, "Thus says the LORD, the God of Israel, "I brought up Israel out of Egypt, and I rescued you from the hand of the Egyptians and from the hand of all the kingdoms that were oppressing you."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 10, 19, 'But today you have rejected your God, who saves you from all your calamities and your distresses; and you have said, "No! but set a king over us." Now therefore present yourselves before the LORD by your tribes and by your clans."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 10, 20, 'Then Samuel brought all the tribes of Israel near, and the tribe of Benjamin was taken by lot.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 10, 21, 'He brought the tribe of Benjamin near by its families, and the family of the Matrites was taken by lot. Finally he brought the family of the Matrites near man by man, and Saul the son of Kish was taken by lot. But when they sought him, he could not be found.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 10, 22, 'So they inquired again of the LORD, "Did the man come here?" and the LORD said, "See, he has hidden himself among the baggage."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 10, 23, 'Then they ran and brought him from there. When he took his stand among the people, he was head and shoulders taller than any of them.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 10, 24, 'Samuel said to all the people, "Do you see the one whom the LORD has chosen? There is no one like him among all the people." And all the people shouted, "Long live the king!"', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 10, 25, 'Samuel told the people the rights and duties of the kingship; and he wrote them in a book and laid it up before the LORD. Then Samuel sent all the people back to their homes.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 10, 26, 'Saul also went to his home at Gibeah, and with him went warriors whose hearts God had touched.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 10, 27, 'But some worthless fellows said, "How can this man save us?" They despised him and brought him no present. But he held his peace.
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(9, '1 Sam', '1 Samuel', 11, 1, 'About a month later, Nahash the Ammonite went up and besieged Jabesh-gilead; and all the men of Jabesh said to Nahash, "Make a treaty with us, and we will serve you."', 'en', 'NRSV-CE', 'Saul Defeats the Ammonites'),
(9, '1 Sam', '1 Samuel', 11, 2, 'But Nahash the Ammonite said to them, "On this condition I will make a treaty with you, namely that I gouge out everyone"s right eye, and thus put disgrace upon all Israel."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 11, 3, 'The elders of Jabesh said to him, "Give us seven days" respite that we may send messengers through all the territory of Israel. Then, if there is no one to save us, we will give ourselves up to you."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 11, 4, 'When the messengers came to Gibeah of Saul, they reported the matter in the hearing of the people; and all the people wept aloud.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 11, 5, 'Now Saul was coming from the field behind the oxen; and Saul said, "What is the matter with the people, that they are weeping?" So they told him the message from the inhabitants of Jabesh.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 11, 6, 'And the spirit of God came upon Saul in power when he heard these words, and his anger was greatly kindled.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 11, 7, 'He took a yoke of oxen, and cut them in pieces and sent them throughout all the territory of Israel by messengers, saying, "Whoever does not come out after Saul and Samuel, so shall it be done to his oxen!" Then the dread of the LORD fell upon the people, and they came out as one.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 11, 8, 'When he mustered them at Bezek, those from Israel were three hundred thousand, and those from Judah seventy thousand.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 11, 9, 'They said to the messengers who had come, "Thus shall you say to the inhabitants of Jabesh-gilead: "Tomorrow, by the time the sun is hot, you shall have deliverance."" When the messengers came and told the inhabitants of Jabesh, they rejoiced.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 11, 10, 'So the inhabitants of Jabesh said, "Tomorrow we will give ourselves up to you, and you may do to us whatever seems good to you."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 11, 11, 'The next day Saul put the people in three companies. At the morning watch they came into the camp and cut down the Ammonites until the heat of the day; and those who survived were scattered, so that no two of them were left together.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 11, 12, 'The people said to Samuel, "Who is it that said, "Shall Saul reign over us?" Give them to us so that we may put them to death."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 11, 13, 'But Saul said, "No one shall be put to death this day, for today the LORD has brought deliverance to Israel."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 11, 14, 'Samuel said to the people, "Come, let us go to Gilgal and there renew the kingship."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 11, 15, 'So all the people went to Gilgal, and there they made Saul king before the LORD in Gilgal. There they sacrificed offerings of well-being before the LORD, and there Saul and all the Israelites rejoiced greatly.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(9, '1 Sam', '1 Samuel', 12, 1, 'Samuel said to all Israel, "I have listened to you in all that you have said to me, and have set a king over you.', 'en', 'NRSV-CE', 'Samuel"s Farewell Address'),
(9, '1 Sam', '1 Samuel', 12, 2, 'See, it is the king who leads you now; I am old and gray, but my sons are with you. I have led you from my youth until this day.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 12, 3, 'Here I am; testify against me before the LORD and before his anointed. Whose ox have I taken? Or whose donkey have I taken? Or whom have I defrauded? Whom have I oppressed? Or from whose hand have I taken a bribe to blind my eyes with it? Testify against me and I will restore it to you."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 12, 4, 'They said, "You have not defrauded us or oppressed us or taken anything from the hand of anyone."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 12, 5, 'He said to them, "The LORD is witness against you, and his anointed is witness this day, that you have not found anything in my hand." And they said, "He is witness."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 12, 6, 'Samuel said to the people, "The LORD is witness, who appointed Moses and Aaron and brought your ancestors up out of the land of Egypt.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 12, 7, 'Now therefore take your stand, so that I may enter into judgment with you before the LORD, and I will declare to you all the saving deeds of the LORD that he performed for you and for your ancestors.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 12, 8, 'When Jacob went into Egypt and the Egyptians oppressed them, then your ancestors cried to the LORD and the LORD sent Moses and Aaron, who brought forth your ancestors out of Egypt, and settled them in this place.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 12, 9, 'But they forgot the LORD their God; and he sold them into the hand of Sisera, commander of the army of King Jabin of Hazor, and into the hand of the Philistines, and into the hand of the king of Moab; and they fought against them.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 12, 10, 'Then they cried to the LORD, and said, "We have sinned, because we have forsaken the LORD, and have served the Baals and the Astartes; but now rescue us out of the hand of our enemies, and we will serve you."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 12, 11, 'And the LORD sent Jerubbaal and Barak, and Jephthah, and Samson, and rescued you out of the hand of your enemies on every side; and you lived in safety.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 12, 12, 'But when you saw that King Nahash of the Ammonites came against you, you said to me, "No, but a king shall reign over us," though the LORD your God was your king.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 12, 13, 'See, here is the king whom you have chosen, for whom you have asked; see, the LORD has set a king over you.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 12, 14, 'If you will fear the LORD and serve him and heed his voice and not rebel against the commandment of the LORD, and if both you and the king who reigns over you will follow the LORD your God, it will be well;', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 12, 15, 'but if you will not heed the voice of the LORD, but rebel against the commandment of the LORD, then the hand of the LORD will be against you and your king.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 12, 16, 'Now therefore take your stand and see this great thing that the LORD will do before your eyes.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 12, 17, 'Is it not the wheat harvest today? I will call upon the LORD, that he may send thunder and rain; and you shall know and see that the wickedness that you have done in the sight of the LORD is great in demanding a king for yourselves."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 12, 18, 'So Samuel called upon the LORD, and the LORD sent thunder and rain that day; and all the people greatly feared the LORD and Samuel.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 12, 19, 'All the people said to Samuel, "Pray to the LORD your God for your servants, so that we may not die; for we have added to all our sins the evil of demanding a king for ourselves."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 12, 20, 'And Samuel said to the people, "Do not be afraid; you have done all this evil, yet do not turn aside from following the LORD, but serve the LORD with all your heart;', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 12, 21, 'and do not turn aside after useless things that cannot profit or save, for they are useless.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 12, 22, 'For the LORD will not cast away his people, for his great name"s sake, because it has pleased the LORD to make you a people for himself.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 12, 23, 'Moreover as for me, far be it from me that I should sin against the LORD by ceasing to pray for you; and I will instruct you in the good and the right way.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 12, 24, 'Only fear the LORD, and serve him faithfully with all your heart; for consider what great things he has done for you.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 12, 25, 'But if you still do wickedly, you shall be swept away, both you and your king."', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(9, '1 Sam', '1 Samuel', 13, 1, 'Saul was... years old when he began to reign; and he reigned... and two years over Israel.', 'en', 'NRSV-CE', 'Saul"s Unlawful Sacrifice'),
(9, '1 Sam', '1 Samuel', 13, 2, 'Saul chose three thousand out of Israel; two thousand were with Saul in Michmash and the hill country of Bethel, and a thousand were with Jonathan in Gibeah of Benjamin; the rest of the people he sent home to their tents.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 13, 3, 'Jonathan defeated the garrison of the Philistines that was at Geba; and the Philistines heard of it. And Saul blew the trumpet throughout all the land, saying, "Let the Hebrews hear!"', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 13, 4, 'When all Israel heard that Saul had defeated the garrison of the Philistines, and also that Israel had become odious to the Philistines, the people were called out to join Saul at Gilgal.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 13, 5, 'The Philistines mustered to fight with Israel, thirty thousand chariots, and six thousand horsemen, and troops like the sand on the seashore in multitude; they came up and encamped at Michmash, to the east of Beth-aven.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 13, 6, 'When the Israelites saw that they were in distress (for the troops were hard pressed), the people hid themselves in caves and in holes and in rocks and in tombs and in cisterns.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 13, 7, 'Some Hebrews crossed the Jordan to the land of Gad and Gilead. Saul was still at Gilgal, and all the people followed him trembling.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 13, 8, 'He waited seven days, the time appointed by Samuel; but Samuel did not come to Gilgal, and the people began to slip away from Saul.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 13, 9, 'So Saul said, "Bring the burnt offering here to me, and the offerings of well-being." And he offered the burnt offering.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 13, 10, 'As soon as he had finished offering the burnt offering, Samuel arrived; and Saul went out to meet him and salute him.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 13, 11, 'Samuel said, "What have you done?" Saul replied, "When I saw that the people were slipping away from me, and that you did not come within the days appointed, and that the Philistines were mustering at Michmash,', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 13, 12, 'I said, "Now the Philistines will come down upon me at Gilgal, and I have not entreated the favor of the LORD"; so I forced myself, and offered the burnt offering."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 13, 13, 'Samuel said to Saul, "You have done foolishly; you have not kept the commandment of the LORD your God, which he commanded you. The LORD would have established your kingdom over Israel forever,', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 13, 14, 'but now your kingdom will not continue; the LORD has sought out a man after his own heart; and the LORD has appointed him to be ruler over his people, because you have not kept what the LORD commanded you."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 13, 15, 'And Samuel left and went on his way from Gilgal. The rest of the people followed Saul to join the army; they went up from Gilgal toward Gibeah of Benjamin.
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(9, '1 Sam', '1 Samuel', 14, 1, 'One day Jonathan son of Saul said to the young man who carried his armor, "Come, let us go over to the Philistine garrison on the other side." But he did not tell his father.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 14, 2, 'Saul was staying in the outskirts of Gibeah under the pomegranate tree that is at Migron; the troops that were with him were about six hundred men,', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 14, 3, 'along with Ahijah son of Ahitub, Ichabod"s brother, son of Phinehas son of Eli, the priest of the LORD in Shiloh, carrying an ephod. Now the people did not know that Jonathan had gone.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 14, 4, 'In the pass, by which Jonathan tried to go over to the Philistine garrison, there was a rocky crag on one side and a rocky crag on the other; the name of the one was Bozez, and the name of the other Seneh.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 14, 5, 'One crag rose on the north in front of Michmash, and the other on the south in front of Geba.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 14, 6, 'Jonathan said to the young man who carried his armor, "Come, let us go over to the garrison of these uncircumcised; it may be that the LORD will act for us; for nothing can hinder the LORD from saving by many or by few."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 14, 7, 'His armor-bearer said to him, "Do all that your mind inclines to. I am with you; as your mind is, so is mine."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 14, 8, 'Then Jonathan said, "Now we will cross over to those men and will show ourselves to them.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 14, 9, 'If they say to us, "Wait until we come to you," then we will stand still in our place, and we will not go up to them.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 14, 10, 'But if they say, "Come up to us," then we will go up; for the LORD has given them into our hand. That will be the sign for us."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 14, 11, 'So both of them showed themselves to the garrison of the Philistines; and the Philistines said, "Look, Hebrews are coming out of the holes where they have hidden themselves."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 14, 12, 'The men of the garrison hailed Jonathan and his armor-bearer, saying, "Come up to us, and we will show you something." Jonathan said to his armor-bearer, "Come up after me; for the LORD has given them into the hand of Israel."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 14, 13, 'Then Jonathan climbed up on his hands and feet, with his armor-bearer following after him. The Philistines fell before Jonathan, and his armor-bearer, coming after him, killed them.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 14, 14, 'In that first slaughter Jonathan and his armor-bearer killed about twenty men within an area about half a furrow long in an acre of land.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 14, 15, 'There was a panic in the camp, in the field, and among all the people; the garrison and even the raiders trembled; the earth quaked; and it became a very great panic.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 14, 16, 'Saul"s lookouts in Gibeah of Benjamin were watching as the multitude was surging back and forth.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 14, 17, 'Then Saul said to the troops that were with him, "Call the roll and see who has gone from us." When they had called the roll, Jonathan and his armor-bearer were not there.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 14, 18, 'Saul said to Ahijah, "Bring the ark of God here." For at that time the ark of God went with the Israelites.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 14, 19, 'While Saul was talking to the priest, the tumult in the camp of the Philistines increased more and more; and Saul said to the priest, "Withdraw your hand."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 14, 20, 'Then Saul and all the people who were with him rallied and went into the battle; and every sword was against the other, so that there was very great confusion.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 14, 21, 'Now the Hebrews who previously had been with the Philistines and had gone up with them into the camp turned and joined the Israelites who were with Saul and Jonathan.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 14, 22, 'Likewise, when all the Israelites who had gone into hiding in the hill country of Ephraim heard that the Philistines were fleeing, they too followed closely after them in the battle.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 14, 23, 'So the LORD gave Israel the victory that day.
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(9, '1 Sam', '1 Samuel', 15, 1, 'Samuel said to Saul, "The LORD sent me to anoint you king over his people Israel; now therefore listen to the words of the LORD.', 'en', 'NRSV-CE', 'Saul Defeats the Amalekites but Spares Their King'),
(9, '1 Sam', '1 Samuel', 15, 2, 'Thus says the LORD of hosts, "I will punish the Amalekites for what they did in opposing the Israelites when they came up out of Egypt.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 15, 3, 'Now go and attack Amalek, and utterly destroy all that they have; do not spare them, but kill both man and woman, child and infant, ox and sheep, camel and donkey.""', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 15, 4, 'So Saul summoned the people, and numbered them in Telaim, two hundred thousand foot soldiers, and ten thousand soldiers of Judah.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 15, 5, 'Saul came to the city of the Amalekites and lay in wait in the valley.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 15, 6, 'Saul said to the Kenites, "Go! Leave! Withdraw from among the Amalekites, or I will destroy you with them; for you showed kindness to all the people of Israel when they came up out of Egypt." So the Kenites withdrew from the Amalekites.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 15, 7, 'Saul defeated the Amalekites, from Havilah as far as Shur, which is east of Egypt.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 15, 8, 'He took King Agag of the Amalekites alive, but utterly destroyed all the people with the edge of the sword.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 15, 9, 'Saul and the people spared Agag, and the best of the sheep and of the cattle and of the fatlings, and the lambs, and all that was valuable, and would not utterly destroy them; all that was despised and worthless they utterly destroyed.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 15, 10, 'The word of the LORD came to Samuel:', 'en', 'NRSV-CE', 'Saul Rejected as King'),
(9, '1 Sam', '1 Samuel', 15, 11, '"I regret that I made Saul king, for he has turned back from following me, and has not carried out my commands." Samuel was angry; and he cried out to the LORD all night.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 15, 12, 'Samuel rose early in the morning to meet Saul, and Samuel was told, "Saul went to Carmel, where he set up a monument for himself, and on returning he passed on down to Gilgal."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 15, 13, 'When Samuel came to Saul, Saul said to him, "May you be blessed by the LORD; I have carried out the command of the LORD."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 15, 14, 'But Samuel said, "What then is this bleating of sheep in my ears, and the lowing of cattle that I hear?"', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 15, 15, 'Saul said, "They have brought them from the Amalekites; for the people spared the best of the sheep and the cattle, to sacrifice to the LORD your God; but the rest we have utterly destroyed."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 15, 16, 'Then Samuel said to Saul, "Stop! I will tell you what the LORD said to me last night." He replied, "Speak."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 15, 17, 'Samuel said, "Though you are little in your own eyes, are you not the head of the tribes of Israel? The LORD anointed you king over Israel.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 15, 18, 'And the LORD sent you on a mission, and said, "Go, utterly destroy the sinners, the Amalekites, and fight against them until they are consumed."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 15, 19, 'Why then did you not obey the voice of the LORD? Why did you swoop down on the spoil, and do what was evil in the sight of the LORD?"', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 15, 20, 'Saul said to Samuel, "I have obeyed the voice of the LORD, I have gone on the mission on which the LORD sent me, I have brought Agag the king of Amalek, and I have utterly destroyed the Amalekites.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 15, 21, 'But from the spoil the people took sheep and cattle, the best of the things devoted to destruction, to sacrifice to the LORD your God in Gilgal."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 15, 22, 'And Samuel said,
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(9, '1 Sam', '1 Samuel', 16, 1, 'The LORD said to Samuel, "How long will you grieve over Saul? I have rejected him from being king over Israel. Fill your horn with oil and set out; I will send you to Jesse the Bethlehemite, for I have provided for myself a king among his sons."', 'en', 'NRSV-CE', 'David Anointed as King'),
(9, '1 Sam', '1 Samuel', 16, 2, 'Samuel said, "How can I go? If Saul hears of it, he will kill me." And the LORD said, "Take a heifer with you, and say, "I have come to sacrifice to the LORD."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 16, 3, 'Invite Jesse to the sacrifice, and I will show you what you shall do; and you shall anoint for me the one whom I name to you."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 16, 4, 'Samuel did what the LORD commanded, and came to Bethlehem. The elders of the city came to meet him trembling, and said, "Do you come peaceably?"', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 16, 5, 'He said, "Peaceably; I have come to sacrifice to the LORD; sanctify yourselves and come with me to the sacrifice." And he sanctified Jesse and his sons and invited them to the sacrifice.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 16, 6, 'When they came, he looked on Eliab and thought, "Surely the LORD"s anointed is now before the LORD."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 16, 7, 'But the LORD said to Samuel, "Do not look on his appearance or on the height of his stature, because I have rejected him; for the LORD does not see as mortals see; they look on the outward appearance, but the LORD looks on the heart."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 16, 8, 'Then Jesse called Abinadab, and made him pass before Samuel. He said, "Neither has the LORD chosen this one."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 16, 9, 'Then Jesse made Shammah pass by. And he said, "Neither has the LORD chosen this one."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 16, 10, 'Jesse made seven of his sons pass before Samuel, and Samuel said to Jesse, "The LORD has not chosen any of these."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 16, 11, 'Samuel said to Jesse, "Are all your sons here?" And he said, "There remains yet the youngest, but he is keeping the sheep." And Samuel said to Jesse, "Send and bring him; for we will not sit down until he comes here."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 16, 12, 'He sent and brought him in. Now he was ruddy, and had beautiful eyes, and was handsome. The LORD said, "Rise and anoint him; for this is the one."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 16, 13, 'Then Samuel took the horn of oil, and anointed him in the presence of his brothers; and the spirit of the LORD came mightily upon David from that day forward. Samuel then set out and went to Ramah.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 16, 14, 'Now the spirit of the LORD departed from Saul, and an evil spirit from the LORD tormented him.', 'en', 'NRSV-CE', 'David Plays the Lyre for Saul'),
(9, '1 Sam', '1 Samuel', 16, 15, 'And Saul"s servants said to him, "See now, an evil spirit from God is tormenting you.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 16, 16, 'Let our lord now command the servants who attend you to look for someone who is skillful in playing the lyre; and when the evil spirit from God is upon you, he will play it, and you will feel better."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 16, 17, 'So Saul said to his servants, "Provide for me someone who can play well, and bring him to me."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 16, 18, 'One of the young men answered, "I have seen a son of Jesse the Bethlehemite who is skillful in playing, a man of valor, a warrior, prudent in speech, and a man of good presence; and the LORD is with him."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 16, 19, 'So Saul sent messengers to Jesse, and said, "Send me your son David who is with the sheep."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 16, 20, 'Jesse took a donkey loaded with bread, a skin of wine, and a kid, and sent them by his son David to Saul.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 16, 21, 'And David came to Saul, and entered his service. Saul loved him greatly, and he became his armor-bearer.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 16, 22, 'Saul sent to Jesse, saying, "Let David remain in my service, for he has found favor in my sight."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 16, 23, 'And whenever the evil spirit from God came upon Saul, David took the lyre and played it with his hand, and Saul would be relieved and feel better, and the evil spirit would depart from him.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(9, '1 Sam', '1 Samuel', 17, 1, 'Now the Philistines gathered their armies for battle; they were gathered at Socoh, which belongs to Judah, and encamped between Socoh and Azekah, in Ephes-dammim.', 'en', 'NRSV-CE', 'David and Goliath'),
(9, '1 Sam', '1 Samuel', 17, 2, 'Saul and the Israelites gathered and encamped in the valley of Elah, and formed ranks against the Philistines.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 17, 3, 'The Philistines stood on the mountain on the one side, and Israel stood on the mountain on the other side, with a valley between them.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 17, 4, 'And there came out from the camp of the Philistines a champion named Goliath, of Gath, whose height was six cubits and a span.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 17, 5, 'He had a helmet of bronze on his head, and he was armed with a coat of mail; the weight of the coat was five thousand shekels of bronze.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 17, 6, 'He had greaves of bronze on his legs and a javelin of bronze slung between his shoulders.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 17, 7, 'The shaft of his spear was like a weaver"s beam, and his spear"s head weighed six hundred shekels of iron; and his shield-bearer went before him.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 17, 8, 'He stood and shouted to the ranks of Israel, "Why have you come out to draw up for battle? Am I not a Philistine, and are you not servants of Saul? Choose a man for yourselves, and let him come down to me.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 17, 9, 'If he is able to fight with me and kill me, then we will be your servants; but if I prevail against him and kill him, then you shall be our servants and serve us."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 17, 10, 'And the Philistine said, "Today I defy the ranks of Israel! Give me a man, that we may fight together."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 17, 11, 'When Saul and all Israel heard these words of the Philistine, they were dismayed and greatly afraid.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 17, 12, 'Now David was the son of an Ephrathite of Bethlehem in Judah, named Jesse, who had eight sons. In the days of Saul the man was already old and advanced in years.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 17, 13, 'The three eldest sons of Jesse had followed Saul to the battle; the names of his three sons who went to the battle were Eliab the firstborn, and next to him Abinadab, and the third Shammah.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 17, 14, 'David was the youngest; the three eldest followed Saul,', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 17, 15, 'but David went back and forth from Saul to feed his father"s sheep at Bethlehem.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 17, 16, 'For forty days the Philistine came forward and took his stand, morning and evening.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 17, 17, 'Jesse said to his son David, "Take for your brothers an ephah of this parched grain and these ten loaves, and carry them quickly to the camp to your brothers;', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 17, 18, 'also take these ten cheeses to the commander of their thousand. See how your brothers fare, and bring some token from them."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 17, 19, 'Now Saul, and they, and all the men of Israel, were in the valley of Elah, fighting with the Philistines.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 17, 20, 'David rose early in the morning, left the sheep with a keeper, took the provisions, and went as Jesse had commanded him. He came to the encampment as the army was going forth to the battle line, shouting the war cry.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 17, 21, 'Israel and the Philistines drew up for battle, army against army.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 17, 22, 'David left the things in charge of the keeper of the baggage, ran to the ranks, and went and greeted his brothers.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 17, 23, 'As he talked with them, the champion, the Philistine of Gath, Goliath by name, came up out of the ranks of the Philistines, and spoke the same words as before. And David heard him.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 17, 24, 'All the Israelites, when they saw the man, fled from him and were very much afraid.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 17, 25, 'The Israelites said, "Have you seen this man who has come up? Surely he has come up to defy Israel. The king will greatly enrich the man who kills him, and will give him his daughter and make his family free in Israel."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 17, 26, 'David said to the men who stood by him, "What shall be done for the man who kills this Philistine, and takes away the reproach from Israel? For who is this uncircumcised Philistine that he should defy the armies of the living God?"', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 17, 27, 'The people answered him in the same way, "So shall it be done for the man who kills him."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 17, 28, 'His eldest brother Eliab heard him talking to the men; and Eliab"s anger was kindled against David. He said, "Why have you come down? With whom have you left those few sheep in the wilderness? I know your presumption and the evil of your heart; for you have come down just to see the battle."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 17, 29, 'David said, "What have I done now? It was only a question."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 17, 30, 'He turned away from him toward another and spoke in the same way; and the people answered him again as before.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 17, 31, 'When the words that David spoke were heard, they repeated them before Saul; and he sent for him.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 17, 32, 'David said to Saul, "Let no one"s heart fail because of him; your servant will go and fight with this Philistine."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 17, 33, 'Saul said to David, "You are not able to go against this Philistine to fight with him; for you are just a boy, and he has been a warrior from his youth."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 17, 34, 'But David said to Saul, "Your servant used to keep sheep for his father; and whenever a lion or a bear came, and took a lamb from the flock,', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 17, 35, 'I went after it and struck it down, rescuing the lamb from its mouth; and if it turned against me, I would catch it by the jaw, strike it down, and kill it.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 17, 36, 'Your servant has killed both lions and bears; and this uncircumcised Philistine shall be like one of them, since he has defied the armies of the living God."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 17, 37, 'David said, "The LORD, who saved me from the paw of the lion and from the paw of the bear, will save me from the hand of this Philistine." So Saul said to David, "Go, and may the LORD be with you!"', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 17, 38, 'Saul clothed David with his armor; he put a bronze helmet on his head and clothed him with a coat of mail.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 17, 39, 'David strapped Saul"s sword over the armor, and he tried in vain to walk, for he was not used to them. Then David said to Saul, "I cannot walk with these; for I am not used to them." So David removed them.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 17, 40, 'Then he took his staff in his hand, and chose five smooth stones from the wadi, and put them in his shepherd"s bag, in the pouch; his sling was in his hand, and he drew near to the Philistine.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 17, 41, 'The Philistine came on and drew near to David, with his shield-bearer in front of him.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 17, 42, 'When the Philistine looked and saw David, he disdained him, for he was only a youth, ruddy and handsome in appearance.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 17, 43, 'The Philistine said to David, "Am I a dog, that you come to me with sticks?" And the Philistine cursed David by his gods.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 17, 44, 'The Philistine said to David, "Come to me, and I will give your flesh to the birds of the air and to the wild animals of the field."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 17, 45, 'But David said to the Philistine, "You come to me with sword and spear and javelin; but I come to you in the name of the LORD of hosts, the God of the armies of Israel, whom you have defied.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 17, 46, 'This very day the LORD will deliver you into my hand, and I will strike you down and cut off your head; and I will give the dead bodies of the Philistine army this very day to the birds of the air and to the wild animals of the earth, so that all the earth may know that there is a God in Israel,', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 17, 47, 'and that all this assembly may know that the LORD does not save by sword and spear; for the battle is the LORD"s and he will give you into our hand."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 17, 48, 'When the Philistine drew nearer to meet David, David ran quickly toward the battle line to meet the Philistine.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 17, 49, 'David put his hand in his bag, took out a stone, slung it, and struck the Philistine on his forehead; the stone sank into his forehead, and he fell face down on the ground.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 17, 50, 'So David prevailed over the Philistine with a sling and a stone, striking down the Philistine and killing him; there was no sword in David"s hand.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 17, 51, 'Then David ran and stood over the Philistine; he grasped his sword, drew it out of its sheath, and killed him; then he cut off his head with it.
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(9, '1 Sam', '1 Samuel', 18, 1, 'When David had finished speaking to Saul, the soul of Jonathan was bound to the soul of David, and Jonathan loved him as his own soul.', 'en', 'NRSV-CE', 'Jonathan"s Covenant with David'),
(9, '1 Sam', '1 Samuel', 18, 2, 'Saul took him that day and would not let him return to his father"s house.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 18, 3, 'Then Jonathan made a covenant with David, because he loved him as his own soul.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 18, 4, 'Jonathan stripped himself of the robe that he was wearing, and gave it to David, and his armor, and even his sword and his bow and his belt.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 18, 5, 'David went out and was successful wherever Saul sent him; as a result, Saul set him over the army. And all the people, even the servants of Saul, approved.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 18, 6, 'As they were coming home, when David returned from killing the Philistine, the women came out of all the towns of Israel, singing and dancing, to meet King Saul, with tambourines, with songs of joy, and with musical instruments.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 18, 7, 'And the women sang to one another as they made merry,
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(9, '1 Sam', '1 Samuel', 19, 1, 'Saul spoke with his son Jonathan and with all his servants about killing David. But Saul"s son Jonathan took great delight in David.', 'en', 'NRSV-CE', 'Jonathan Intercedes for David'),
(9, '1 Sam', '1 Samuel', 19, 2, 'Jonathan told David, "My father Saul is trying to kill you; therefore be on guard tomorrow morning; stay in a secret place and hide yourself.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 19, 3, 'I will go out and stand beside my father in the field where you are, and I will speak to my father about you; if I learn anything I will tell you."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 19, 4, 'Jonathan spoke well of David to his father Saul, saying to him, "The king should not sin against his servant David, because he has not sinned against you, and because his deeds have been of good service to you;', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 19, 5, 'for he took his life in his hand when he attacked the Philistine, and the LORD brought about a great victory for all Israel. You saw it, and rejoiced; why then will you sin against an innocent person by killing David without cause?"', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 19, 6, 'Saul heeded the voice of Jonathan; Saul swore, "As the LORD lives, he shall not be put to death."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 19, 7, 'So Jonathan called David and related all these things to him. Jonathan then brought David to Saul, and he was in his presence as before.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 19, 8, 'Again there was war, and David went out to fight the Philistines. He launched a heavy attack on them, so that they fled before him.', 'en', 'NRSV-CE', 'Michal Helps David Escape from Saul'),
(9, '1 Sam', '1 Samuel', 19, 9, 'Then an evil spirit from the LORD came upon Saul, as he sat in his house with his spear in his hand, while David was playing music.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 19, 10, 'Saul sought to pin David to the wall with the spear; but he eluded Saul, so that he struck the spear into the wall. David fled and escaped that night.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 19, 11, 'Saul sent messengers to David"s house to keep watch over him, planning to kill him in the morning. David"s wife Michal told him, "If you do not save your life tonight, tomorrow you will be killed."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 19, 12, 'So Michal let David down through the window; he fled away and escaped.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 19, 13, 'Michal took an idol and laid it on the bed; she put a net of goats" hair on its head, and covered it with the clothes.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 19, 14, 'When Saul sent messengers to take David, she said, "He is sick."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 19, 15, 'Then Saul sent the messengers to see David for themselves. He said, "Bring him up to me in the bed, that I may kill him."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 19, 16, 'When the messengers came in, the idol was in the bed, with the covering of goats" hair on its head.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 19, 17, 'Saul said to Michal, "Why have you deceived me like this, and let my enemy go, so that he has escaped?" Michal answered Saul, "He said to me, "Let me go; why should I kill you?""', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 19, 18, 'Now David fled and escaped; he came to Samuel at Ramah, and told him all that Saul had done to him. He and Samuel went and settled at Naioth.', 'en', 'NRSV-CE', 'David Joins Samuel in Ramah'),
(9, '1 Sam', '1 Samuel', 19, 19, 'Saul was told, "David is at Naioth in Ramah."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 19, 20, 'Then Saul sent messengers to take David. When they saw the company of the prophets in a frenzy, with Samuel standing in charge of them, the spirit of God came upon the messengers of Saul, and they also fell into a prophetic frenzy.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 19, 21, 'When Saul was told, he sent other messengers, and they also fell into a frenzy. Saul sent messengers again the third time, and they also fell into a frenzy.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 19, 22, 'Then he himself went to Ramah. He came to the great well that is in Secu; he asked, "Where are Samuel and David?" And someone said, "They are at Naioth in Ramah."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 19, 23, 'He went there, toward Naioth in Ramah; and the spirit of God came upon him. As he was going, he fell into a prophetic frenzy, until he came to Naioth in Ramah.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 19, 24, 'He too stripped off his clothes, and he too fell into a frenzy before Samuel. He lay naked all that day and all that night. Therefore it is said, "Is Saul also among the prophets?"', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(9, '1 Sam', '1 Samuel', 20, 1, 'David fled from Naioth in Ramah. He came before Jonathan and said, "What have I done? What is my guilt? And what is my sin against your father that he is trying to take my life?"', 'en', 'NRSV-CE', 'The Friendship of David and Jonathan'),
(9, '1 Sam', '1 Samuel', 20, 2, 'He said to him, "Far from it! You shall not die. My father does nothing either great or small without disclosing it to me; and why should my father hide this from me? Never!"', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 20, 3, 'But David also swore, "Your father knows well that you like me; and he thinks, "Do not let Jonathan know this, or he will be grieved." But truly, as the LORD lives and as you yourself live, there is but a step between me and death."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 20, 4, 'Then Jonathan said to David, "Whatever you say, I will do for you."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 20, 5, 'David said to Jonathan, "Tomorrow is the new moon, and I should not fail to sit with the king at the meal; but let me go, so that I may hide in the field until the third evening.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 20, 6, 'If your father misses me at all, then say, "David earnestly asked leave of me to run to Bethlehem his city; for there is a yearly sacrifice there for all the family."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 20, 7, 'If he says, "Good!" it will be well with your servant; but if he is angry, then know that evil has been determined by him.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 20, 8, 'Therefore deal kindly with your servant, for you have brought your servant into a sacred covenant with you. But if there is guilt in me, kill me yourself; why should you bring me to your father?"', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 20, 9, 'Jonathan said, "Far be it from you! If I knew that it was decided by my father that evil should come upon you, would I not tell you?"', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 20, 10, 'Then David said to Jonathan, "Who will tell me if your father answers you harshly?"', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 20, 11, 'Jonathan replied to David, "Come, let us go out into the field." So they both went out into the field.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 20, 12, 'Jonathan said to David, "By the LORD, the God of Israel! When I have sounded out my father, about this time tomorrow, or on the third day, if he is well disposed toward David, shall I not then send and disclose it to you?', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 20, 13, 'But if my father intends to do you harm, the LORD do so to Jonathan, and more also, if I do not disclose it to you, and send you away, so that you may go in safety. May the LORD be with you, as he has been with my father.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 20, 14, 'If I am still alive, show me the faithful love of the LORD; but if I die,', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 20, 15, 'never cut off your faithful love from my house, even if the LORD were to cut off every one of the enemies of David from the face of the earth."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 20, 16, 'Thus Jonathan made a covenant with the house of David, saying, "May the LORD seek out the enemies of David."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 20, 17, 'Jonathan made David swear again by his love for him; for he loved him as he loved his own life.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 20, 18, 'Jonathan said to him, "Tomorrow is the new moon; you will be missed, because your place will be empty.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 20, 19, 'On the day after tomorrow, you shall go a long way down; go to the place where you hid yourself earlier, and remain beside the stone there.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 20, 20, 'I will shoot three arrows to the side of it, as though I shot at a mark.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 20, 21, 'Then I will send the boy, saying, "Go, find the arrows." If I say to the boy, "Look, the arrows are on this side of you, collect them," then you are to come, for, as the LORD lives, it is safe for you and there is no danger.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 20, 22, 'But if I say to the young man, "Look, the arrows are beyond you," then go; for the LORD has sent you away.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 20, 23, 'As for the matter about which you and I have spoken, the LORD is witness between you and me forever."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 20, 24, 'So David hid himself in the field. When the new moon came, the king sat at the feast to eat.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 20, 25, 'The king sat upon his seat, as at other times, upon the seat by the wall. Jonathan stood, while Abner sat by Saul"s side; but David"s place was empty.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 20, 26, 'Saul did not say anything that day; for he thought, "Something has befallen him; he is not clean, surely he is not clean."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 20, 27, 'But on the second day, the day after the new moon, David"s place was empty. And Saul said to his son Jonathan, "Why has the son of Jesse not come to the feast, either yesterday or today?"', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 20, 28, 'Jonathan answered Saul, "David earnestly asked leave of me to go to Bethlehem;', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 20, 29, 'he said, "Let me go; for our family is holding a sacrifice in the city, and my brother has commanded me to be there. So now, if I have found favor in your sight, let me get away, and see my brothers." For this reason he has not come to the king"s table."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 20, 30, 'Then Saul"s anger was kindled against Jonathan. He said to him, "You son of a perverse, rebellious woman! Do I not know that you have chosen the son of Jesse to your own shame, and to the shame of your mother"s nakedness?', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 20, 31, 'For as long as the son of Jesse lives upon the earth, neither you nor your kingdom shall be established. Now send and bring him to me, for he shall surely die."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 20, 32, 'Then Jonathan answered his father Saul, "Why should he be put to death? What has he done?"', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 20, 33, 'But Saul threw his spear at him to strike him; so Jonathan knew that it was the decision of his father to put David to death.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 20, 34, 'Jonathan rose from the table in fierce anger and ate no food on the second day of the month, for he was grieved for David, and because his father had disgraced him.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 20, 35, 'In the morning Jonathan went out into the field to the appointment with David, and with him was a little boy.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 20, 36, 'He said to the boy, "Run and find the arrows that I shoot." As the boy ran, he shot an arrow beyond him.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 20, 37, 'When the boy came to the place where Jonathan"s arrow had fallen, Jonathan called after the boy and said, "Is the arrow not beyond you?"', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 20, 38, 'Jonathan called after the boy, "Hurry, be quick, do not linger." So Jonathan"s boy gathered up the arrows and came to his master.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 20, 39, 'But the boy knew nothing; only Jonathan and David knew the arrangement.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 20, 40, 'Jonathan gave his weapons to the boy and said to him, "Go and carry them to the city."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 20, 41, 'As soon as the boy had gone, David rose from beside the stone heap and prostrated himself with his face to the ground. He bowed three times, and they kissed each other, and wept with each other; David wept the more.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 20, 42, 'Then Jonathan said to David, "Go in peace, since both of us have sworn in the name of the LORD, saying, "The LORD shall be between me and you, and between my descendants and your descendants, forever."" He got up and left; and Jonathan went into the city.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(9, '1 Sam', '1 Samuel', 21, 1, 'David came to Nob to the priest Ahimelech. Ahimelech came trembling to meet David, and said to him, "Why are you alone, and no one with you?"', 'en', 'NRSV-CE', 'David and the Holy Bread'),
(9, '1 Sam', '1 Samuel', 21, 2, 'David said to the priest Ahimelech, "The king has charged me with a matter, and said to me, "No one must know anything of the matter about which I send you, and with which I have charged you." I have made an appointment with the young men for such and such a place.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 21, 3, 'Now then, what have you at hand? Give me five loaves of bread, or whatever is here."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 21, 4, 'The priest answered David, "I have no ordinary bread at hand, only holy bread--provided that the young men have kept themselves from women."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 21, 5, 'David answered the priest, "Indeed women have been kept from us as always when I go on an expedition; the vessels of the young men are holy even when it is a common journey; how much more today will their vessels be holy?"', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 21, 6, 'So the priest gave him the holy bread; for there was no bread there except the bread of the Presence, which is removed from before the LORD, to be replaced by hot bread on the day it is taken away.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 21, 7, 'Now a certain man of the servants of Saul was there that day, detained before the LORD; his name was Doeg the Edomite, the chief of Saul"s shepherds.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 21, 8, 'David said to Ahimelech, "Is there no spear or sword here with you? I did not bring my sword or my weapons with me, because the king"s business required haste."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 21, 9, 'The priest said, "The sword of Goliath the Philistine, whom you killed in the valley of Elah, is here wrapped in a cloth behind the ephod; if you will take that, take it, for there is none here except that one." David said, "There is none like it; give it to me."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 21, 10, 'David rose and fled that day from Saul; he went to King Achish of Gath.', 'en', 'NRSV-CE', 'David Flees to Gath'),
(9, '1 Sam', '1 Samuel', 21, 11, 'The servants of Achish said to him, "Is this not David the king of the land? Did they not sing to one another of him in dances,
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(9, '1 Sam', '1 Samuel', 22, 1, 'David left there and escaped to the cave of Adullam; when his brothers and all his father"s house heard of it, they went down there to him.', 'en', 'NRSV-CE', 'David and His Followers at Adullam'),
(9, '1 Sam', '1 Samuel', 22, 2, 'Everyone who was in distress, and everyone who was in debt, and everyone who was discontented gathered to him; and he became captain over them. Those who were with him numbered about four hundred.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 22, 3, 'David went from there to Mizpeh of Moab. He said to the king of Moab, "Please let my father and mother come to you, until I know what God will do for me."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 22, 4, 'He left them with the king of Moab, and they stayed with him all the time that David was in the stronghold.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 22, 5, 'Then the prophet Gad said to David, "Do not remain in the stronghold; leave, and go into the land of Judah." So David left, and went into the forest of Hereth.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 22, 6, 'Saul heard that David and those who were with him had been located. Saul was sitting at Gibeah, under the tamarisk tree on the height, with his spear in his hand, and all his servants were standing around him.', 'en', 'NRSV-CE', 'Saul Slaughters the Priests at Nob'),
(9, '1 Sam', '1 Samuel', 22, 7, 'Saul said to his servants who stood around him, "Hear now, you Benjaminites; will the son of Jesse give every one of you fields and vineyards, will he make you all commanders of thousands and commanders of hundreds?', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 22, 8, 'Is that why all of you have conspired against me? No one discloses to me when my son makes a league with the son of Jesse, none of you is sorry for me or discloses to me that my son has stirred up my servant against me, to lie in wait, as he is doing today."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 22, 9, 'Doeg the Edomite, who was in charge of Saul"s servants, answered, "I saw the son of Jesse coming to Nob, to Ahimelech son of Ahitub;', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 22, 10, 'he inquired of the LORD for him, gave him provisions, and gave him the sword of Goliath the Philistine."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 22, 11, 'The king sent for the priest Ahimelech son of Ahitub and for all his father"s house, the priests who were at Nob; and all of them came to the king.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 22, 12, 'Saul said, "Listen now, son of Ahitub." He answered, "Here I am, my lord."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 22, 13, 'Saul said to him, "Why have you conspired against me, you and the son of Jesse, by giving him bread and a sword, and by inquiring of God for him, so that he has risen against me, to lie in wait, as he is doing today?"', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 22, 14, 'Then Ahimelech answered the king, "Who among all your servants is so faithful as David? He is the king"s son-in-law, and is quick to do your bidding, and is honored in your house.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 22, 15, 'Is today the first time that I have inquired of God for him? By no means! Do not let the king impute anything to his servant or to any member of my father"s house; for your servant has known nothing of all this, much or little."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 22, 16, 'The king said, "You shall surely die, Ahimelech, you and all your father"s house."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 22, 17, 'The king said to the guard who stood around him, "Turn and kill the priests of the LORD, because their hand also is with David; they knew that he fled, and did not disclose it to me." But the servants of the king would not raise their hand to attack the priests of the LORD.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 22, 18, 'Then the king said to Doeg, "You, Doeg, turn and attack the priests." Doeg the Edomite turned and attacked the priests; on that day he killed eighty-five who wore the linen ephod.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 22, 19, 'Nob, the city of the priests, he put to the sword; men and women, children and infants, oxen, donkeys, and sheep, he put to the sword.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 22, 20, 'But one of the sons of Ahimelech son of Ahitub, named Abiathar, escaped and fled after David.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 22, 21, 'Abiathar told David that Saul had killed the priests of the LORD.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 22, 22, 'David said to Abiathar, "I knew on that day, when Doeg the Edomite was there, that he would surely tell Saul. I am responsible for the lives of all your father"s house.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 22, 23, 'Stay with me, and do not be afraid; for the one who seeks my life seeks your life; you will be safe with me."', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(9, '1 Sam', '1 Samuel', 23, 1, 'Now they told David, "The Philistines are fighting against Keilah, and are robbing the threshing floors."', 'en', 'NRSV-CE', 'David Saves the City of Keilah'),
(9, '1 Sam', '1 Samuel', 23, 2, 'David inquired of the LORD, "Shall I go and attack these Philistines?" The LORD said to David, "Go and attack the Philistines and save Keilah."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 23, 3, 'But David"s men said to him, "Look, we are afraid here in Judah; how much more then if we go to Keilah against the armies of the Philistines?"', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 23, 4, 'Then David inquired of the LORD again. The LORD answered him, "Yes, go down to Keilah; for I will give the Philistines into your hand."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 23, 5, 'So David and his men went to Keilah, fought with the Philistines, brought away their livestock, and dealt them a heavy defeat. Thus David rescued the inhabitants of Keilah.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 23, 6, 'When Abiathar son of Ahimelech fled to David at Keilah, he came down with an ephod in his hand.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 23, 7, 'Now it was told Saul that David had come to Keilah. And Saul said, "God has given him into my hand; for he has shut himself in by entering a town that has gates and bars."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 23, 8, 'Saul summoned all the people to war, to go down to Keilah, to besiege David and his men.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 23, 9, 'When David learned that Saul was plotting evil against him, he said to the priest Abiathar, "Bring the ephod here."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 23, 10, 'David said, "O LORD, the God of Israel, your servant has heard that Saul seeks to come to Keilah, to destroy the city on my account.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 23, 11, 'And now, will Saul come down as your servant has heard? O LORD, the God of Israel, I beseech you, tell your servant." The LORD said, "He will come down."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 23, 12, 'Then David said, "Will the men of Keilah surrender me and my men into the hand of Saul?" The LORD said, "They will surrender you."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 23, 13, 'Then David and his men, who were about six hundred, set out and left Keilah; they wandered wherever they could go. When Saul was told that David had escaped from Keilah, he gave up the expedition.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 23, 14, 'David remained in the strongholds in the wilderness, in the hill country of the Wilderness of Ziph. Saul sought him every day, but the LORD did not give him into his hand.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 23, 15, 'David was in the Wilderness of Ziph at Horesh when he learned that Saul had come out to seek his life.', 'en', 'NRSV-CE', 'David Eludes Saul in the Wilderness'),
(9, '1 Sam', '1 Samuel', 23, 16, 'Saul"s son Jonathan set out and came to David at Horesh; there he strengthened his hand through the LORD.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 23, 17, 'He said to him, "Do not be afraid; for the hand of my father Saul shall not find you; you shall be king over Israel, and I shall be second to you; my father Saul also knows that this is so."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 23, 18, 'Then the two of them made a covenant before the LORD; David remained at Horesh, and Jonathan went home.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 23, 19, 'Then some Ziphites went up to Saul at Gibeah and said, "David is hiding among us in the strongholds of Horesh, on the hill of Hachilah, which is south of Jeshimon.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 23, 20, 'Now, O king, whenever you wish to come down, do so; and our part will be to surrender him into the king"s hand."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 23, 21, 'Saul said, "May you be blessed by the LORD for showing me compassion!', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 23, 22, 'Go and make sure once more; find out exactly where he is, and who has seen him there; for I am told that he is very cunning.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 23, 23, 'Look around and learn all the hiding places where he lurks, and come back to me with sure information. Then I will go with you; and if he is in the land, I will search him out among all the thousands of Judah."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 23, 24, 'So they set out and went to Ziph ahead of Saul.
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(9, '1 Sam', '1 Samuel', 24, 1, 'When Saul returned from following the Philistines, he was told, "David is in the wilderness of En-gedi."', 'en', 'NRSV-CE', 'David Spares Saul"s Life'),
(9, '1 Sam', '1 Samuel', 24, 2, 'Then Saul took three thousand chosen men out of all Israel, and went to look for David and his men in the direction of the Rocks of the Wild Goats.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 24, 3, 'He came to the sheepfolds beside the road, where there was a cave; and Saul went in to relieve himself. Now David and his men were sitting in the innermost parts of the cave.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 24, 4, 'The men of David said to him, "Here is the day of which the LORD said to you, "I will give your enemy into your hand, and you shall do to him as it seems good to you."" Then David went and stealthily cut off a corner of Saul"s cloak.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 24, 5, 'Afterward David was stricken to the heart because he had cut off a corner of Saul"s cloak.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 24, 6, 'He said to his men, "The LORD forbid that I should do this thing to my lord, the LORD"s anointed, to raise my hand against him; for he is the LORD"s anointed."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 24, 7, 'So David scolded his men severely and did not permit them to attack Saul. Then Saul got up and left the cave, and went on his way.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 24, 8, 'Afterwards David also rose up and went out of the cave and called after Saul, "My lord the king!" When Saul looked behind him, David bowed with his face to the ground, and did obeisance.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 24, 9, 'David said to Saul, "Why do you listen to the words of those who say, "David seeks to do you harm"?', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 24, 10, 'This very day your eyes have seen how the LORD gave you into my hand in the cave; and some urged me to kill you, but I spared you. I said, "I will not raise my hand against my lord; for he is the LORD"s anointed."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 24, 11, 'See, my father, see the corner of your cloak in my hand; for by the fact that I cut off the corner of your cloak, and did not kill you, you may know for certain that there is no wrong or treason in my hands. I have not sinned against you, though you are hunting me to take my life.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 24, 12, 'May the LORD judge between me and you! May the LORD avenge me on you; but my hand shall not be against you.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 24, 13, 'As the ancient proverb says, "Out of the wicked comes forth wickedness"; but my hand shall not be against you.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 24, 14, 'Against whom has the king of Israel come out? Whom do you pursue? A dead dog? A single flea?', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 24, 15, 'May the LORD therefore be judge, and give sentence between me and you. May he see to it, and plead my cause, and vindicate me against you."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 24, 16, 'When David had finished speaking these words to Saul, Saul said, "Is this your voice, my son David?" Saul lifted up his voice and wept.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 24, 17, 'He said to David, "You are more righteous than I; for you have repaid me good, whereas I have repaid you evil.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 24, 18, 'Today you have explained how you have dealt well with me, in that you did not kill me when the LORD put me into your hands.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 24, 19, 'For who has ever found an enemy, and sent the enemy safely away? So may the LORD reward you with good for what you have done to me this day.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 24, 20, 'Now I know that you shall surely be king, and that the kingdom of Israel shall be established in your hand.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 24, 21, 'Swear to me therefore by the LORD that you will not cut off my descendants after me, and that you will not wipe out my name from my father"s house."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 24, 22, 'So David swore this to Saul. Then Saul went home; but David and his men went up to the stronghold.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(9, '1 Sam', '1 Samuel', 25, 1, 'Now Samuel died; and all Israel assembled and mourned for him. They buried him at his home in Ramah.
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(9, '1 Sam', '1 Samuel', 26, 1, 'Then the Ziphites came to Saul at Gibeah, saying, "David is in hiding on the hill of Hachilah, which is opposite Jeshimon."', 'en', 'NRSV-CE', 'David Spares Saul"s Life a Second Time'),
(9, '1 Sam', '1 Samuel', 26, 2, 'So Saul rose and went down to the Wilderness of Ziph, with three thousand chosen men of Israel, to seek David in the Wilderness of Ziph.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 26, 3, 'Saul encamped on the hill of Hachilah, which is opposite Jeshimon beside the road. But David remained in the wilderness. When he learned that Saul had come after him into the wilderness,', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 26, 4, 'David sent out spies, and learned that Saul had indeed arrived.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 26, 5, 'Then David set out and came to the place where Saul had encamped; and David saw the place where Saul lay, with Abner son of Ner, the commander of his army. Saul was lying within the encampment, while the army was encamped around him.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 26, 6, 'Then David said to Ahimelech the Hittite, and to Joab"s brother Abishai son of Zeruiah, "Who will go down with me into the camp to Saul?" Abishai said, "I will go down with you."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 26, 7, 'So David and Abishai went to the army by night; there Saul lay sleeping within the encampment, with his spear stuck in the ground at his head; and Abner and the army lay around him.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 26, 8, 'Abishai said to David, "God has given your enemy into your hand today; now therefore let me pin him to the ground with one stroke of the spear; I will not strike him twice."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 26, 9, 'But David said to Abishai, "Do not destroy him; for who can raise his hand against the LORD"s anointed, and be guiltless?"', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 26, 10, 'David said, "As the LORD lives, the LORD will strike him down; or his day will come to die; or he will go down into battle and perish.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 26, 11, 'The LORD forbid that I should raise my hand against the LORD"s anointed; but now take the spear that is at his head, and the water jar, and let us go."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 26, 12, 'So David took the spear that was at Saul"s head and the water jar, and they went away. No one saw it, or knew it, nor did anyone awake; for they were all asleep, because a deep sleep from the LORD had fallen upon them.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 26, 13, 'Then David went over to the other side, and stood on top of a hill far away, with a great distance between them.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 26, 14, 'David called to the army and to Abner son of Ner, saying, "Abner! Will you not answer?" Then Abner replied, "Who are you that calls to the king?"', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 26, 15, 'David said to Abner, "Are you not a man? Who is like you in Israel? Why then have you not kept watch over your lord the king? For one of the people came in to destroy your lord the king.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 26, 16, 'This thing that you have done is not good. As the LORD lives, you deserve to die, because you have not kept watch over your lord, the LORD"s anointed. See now, where is the king"s spear, or the water jar that was at his head?"', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 26, 17, 'Saul recognized David"s voice, and said, "Is this your voice, my son David?" David said, "It is my voice, my lord, O king."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 26, 18, 'And he added, "Why does my lord pursue his servant? For what have I done? What guilt is on my hands?', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 26, 19, 'Now therefore let my lord the king hear the words of his servant. If it is the LORD who has stirred you up against me, may he accept an offering; but if it is mortals, may they be cursed before the LORD, for they have driven me out today from my share in the heritage of the LORD, saying, "Go, serve other gods."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 26, 20, 'Now therefore, do not let my blood fall to the ground, away from the presence of the LORD; for the king of Israel has come out to seek a single flea, like one who hunts a partridge in the mountains."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 26, 21, 'Then Saul said, "I have done wrong; come back, my son David, for I will never harm you again, because my life was precious in your sight today; I have been a fool, and have made a great mistake."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 26, 22, 'David replied, "Here is the spear, O king! Let one of the young men come over and get it.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 26, 23, 'The LORD rewards everyone for his righteousness and his faithfulness; for the LORD gave you into my hand today, but I would not raise my hand against the LORD"s anointed.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 26, 24, 'As your life was precious today in my sight, so may my life be precious in the sight of the LORD, and may he rescue me from all tribulation."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 26, 25, 'Then Saul said to David, "Blessed be you, my son David! You will do many things and will succeed in them." So David went his way, and Saul returned to his place.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(9, '1 Sam', '1 Samuel', 27, 1, 'David said in his heart, "I shall now perish one day by the hand of Saul; there is nothing better for me than to escape to the land of the Philistines; then Saul will despair of seeking me any longer within the borders of Israel, and I shall escape out of his hand."', 'en', 'NRSV-CE', 'David Serves King Achish of Gath'),
(9, '1 Sam', '1 Samuel', 27, 2, 'So David set out and went over, he and the six hundred men who were with him, to King Achish son of Maoch of Gath.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 27, 3, 'David stayed with Achish at Gath, he and his troops, every man with his household, and David with his two wives, Ahinoam of Jezreel, and Abigail of Carmel, Nabal"s widow.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 27, 4, 'When Saul was told that David had fled to Gath, he no longer sought for him.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 27, 5, 'Then David said to Achish, "If I have found favor in your sight, let a place be given me in one of the country towns, so that I may live there; for why should your servant live in the royal city with you?"', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 27, 6, 'So that day Achish gave him Ziklag; therefore Ziklag has belonged to the kings of Judah to this day.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 27, 7, 'The length of time that David lived in the country of the Philistines was one year and four months.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 27, 8, 'Now David and his men went up and made raids on the Geshurites, the Girzites, and the Amalekites; for these were the landed settlements from Telam on the way to Shur and on to the land of Egypt.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 27, 9, 'David struck the land, leaving neither man nor woman alive, but took away the sheep, the oxen, the donkeys, the camels, and the clothing, and came back to Achish.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 27, 10, 'When Achish asked, "Against whom have you made a raid today?" David would say, "Against the Negeb of Judah," or "Against the Negeb of the Jerahmeelites," or, "Against the Negeb of the Kenites."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 27, 11, 'David left neither man nor woman alive to be brought back to Gath, thinking, "They might tell about us, and say, "David has done so and so."" Such was his practice all the time he lived in the country of the Philistines.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 27, 12, 'Achish trusted David, thinking, "He has made himself utterly abhorrent to his people Israel; therefore he shall always be my servant."', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(9, '1 Sam', '1 Samuel', 28, 1, 'In those days the Philistines gathered their forces for war, to fight against Israel. Achish said to David, "You know, of course, that you and your men are to go out with me in the army."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 28, 2, 'David said to Achish, "Very well, then you shall know what your servant can do." Achish said to David, "Very well, I will make you my bodyguard for life."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 28, 3, 'Now Samuel had died, and all Israel had mourned for him and buried him in Ramah, his own city. Saul had expelled the mediums and the wizards from the land.', 'en', 'NRSV-CE', 'Saul Consults a Medium'),
(9, '1 Sam', '1 Samuel', 28, 4, 'The Philistines assembled, and came and encamped at Shunem. Saul gathered all Israel, and they encamped at Gilboa.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 28, 5, 'When Saul saw the army of the Philistines, he was afraid, and his heart trembled greatly.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 28, 6, 'When Saul inquired of the LORD, the LORD did not answer him, not by dreams, or by Urim, or by prophets.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 28, 7, 'Then Saul said to his servants, "Seek out for me a woman who is a medium, so that I may go to her and inquire of her." His servants said to him, "There is a medium at Endor."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 28, 8, 'So Saul disguised himself and put on other clothes and went there, he and two men with him. They came to the woman by night. And he said, "Consult a spirit for me, and bring up for me the one whom I name to you."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 28, 9, 'The woman said to him, "Surely you know what Saul has done, how he has cut off the mediums and the wizards from the land. Why then are you laying a snare for my life to bring about my death?"', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 28, 10, 'But Saul swore to her by the LORD, "As the LORD lives, no punishment shall come upon you for this thing."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 28, 11, 'Then the woman said, "Whom shall I bring up for you?" He answered, "Bring up Samuel for me."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 28, 12, 'When the woman saw Samuel, she cried out with a loud voice; and the woman said to Saul, "Why have you deceived me? You are Saul!"', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 28, 13, 'The king said to her, "Have no fear; what do you see?" The woman said to Saul, "I see a divine being coming up out of the ground."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 28, 14, 'He said to her, "What is his appearance?" She said, "An old man is coming up; he is wrapped in a robe." So Saul knew that it was Samuel, and he bowed with his face to the ground, and did obeisance.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 28, 15, 'Then Samuel said to Saul, "Why have you disturbed me by bringing me up?" Saul answered, "I am in great distress, for the Philistines are warring against me, and God has turned away from me and answers me no more, either by prophets or by dreams; so I have summoned you to tell me what I should do."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 28, 16, 'Samuel said, "Why then do you ask me, since the LORD has turned from you and become your enemy?', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 28, 17, 'The LORD has done to you just as he spoke by me; for the LORD has torn the kingdom out of your hand, and given it to your neighbor, David.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 28, 18, 'Because you did not obey the voice of the LORD, and did not carry out his fierce wrath against Amalek, therefore the LORD has done this thing to you today.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 28, 19, 'Moreover the LORD will give Israel along with you into the hands of the Philistines; and tomorrow you and your sons shall be with me; the LORD will also give the army of Israel into the hands of the Philistines."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 28, 20, 'Immediately Saul fell full length on the ground, filled with fear because of the words of Samuel; and there was no strength in him, for he had eaten nothing all day and all night.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 28, 21, 'The woman came to Saul, and when she saw that he was terrified, she said to him, "Your servant has listened to you; I have taken my life in my hand, and have listened to what you have said to me.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 28, 22, 'Now therefore, you also listen to your servant; let me set a morsel of bread before you. Eat, that you may have strength when you go on your way."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 28, 23, 'He refused, and said, "I will not eat." But his servants, together with the woman, urged him; and he listened to their words. So he got up from the ground and sat on the bed.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 28, 24, 'Now the woman had a fatted calf in the house. She quickly slaughtered it, and she took flour, kneaded it, and baked unleavened cakes.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 28, 25, 'She put them before Saul and his servants, and they ate. Then they rose and went away that night.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(9, '1 Sam', '1 Samuel', 29, 1, 'Now the Philistines gathered all their forces at Aphek, while the Israelites were encamped by the fountain that is in Jezreel.', 'en', 'NRSV-CE', 'The Philistines Reject David'),
(9, '1 Sam', '1 Samuel', 29, 2, 'As the lords of the Philistines were passing on by hundreds and by thousands, and David and his men were passing on in the rear with Achish,', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 29, 3, 'the commanders of the Philistines said, "What are these Hebrews doing here?" Achish said to the commanders of the Philistines, "Is this not David, the servant of King Saul of Israel, who has been with me now for days and years? Since he deserted to me I have found no fault in him to this day."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 29, 4, 'But the commanders of the Philistines were angry with him; and the commanders of the Philistines said to him, "Send the man back, so that he may return to the place that you have assigned to him; he shall not go down with us to battle, or else he may become an adversary to us in the battle. For how could this fellow reconcile himself to his lord? Would it not be with the heads of the men here?', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 29, 5, 'Is this not David, of whom they sing to one another in dances,
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(9, '1 Sam', '1 Samuel', 30, 1, 'Now when David and his men came to Ziklag on the third day, the Amalekites had made a raid on the Negeb and on Ziklag. They had attacked Ziklag, burned it down,', 'en', 'NRSV-CE', 'David Avenges the Destruction of Ziklag'),
(9, '1 Sam', '1 Samuel', 30, 2, 'and taken captive the women and all who were in it, both small and great; they killed none of them, but carried them off, and went their way.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 30, 3, 'When David and his men came to the city, they found it burned down, and their wives and sons and daughters taken captive.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 30, 4, 'Then David and the people who were with him raised their voices and wept, until they had no more strength to weep.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 30, 5, 'David"s two wives also had been taken captive, Ahinoam of Jezreel, and Abigail the widow of Nabal of Carmel.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 30, 6, 'David was in great danger; for the people spoke of stoning him, because all the people were bitter in spirit for their sons and daughters. But David strengthened himself in the LORD his God.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 30, 7, 'David said to the priest Abiathar son of Ahimelech, "Bring me the ephod." So Abiathar brought the ephod to David.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 30, 8, 'David inquired of the LORD, "Shall I pursue this band? Shall I overtake them?" He answered him, "Pursue; for you shall surely overtake and shall surely rescue."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 30, 9, 'So David set out, he and the six hundred men who were with him. They came to the Wadi Besor, where those stayed who were left behind.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 30, 10, 'But David went on with the pursuit, he and four hundred men; two hundred stayed behind, too exhausted to cross the Wadi Besor.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 30, 11, 'In the open country they found an Egyptian, and brought him to David. They gave him bread and he ate; they gave him water to drink;', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 30, 12, 'they also gave him a piece of fig cake and two clusters of raisins. When he had eaten, his spirit revived; for he had not eaten bread or drunk water for three days and three nights.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 30, 13, 'Then David said to him, "To whom do you belong? Where are you from?" He said, "I am a young man of Egypt, servant to an Amalekite. My master left me behind because I fell sick three days ago.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 30, 14, 'We had made a raid on the Negeb of the Cherethites and on that which belongs to Judah and on the Negeb of Caleb; and we burned Ziklag down."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 30, 15, 'David said to him, "Will you take me down to this raiding party?" He said, "Swear to me by God that you will not kill me, or hand me over to my master, and I will take you down to them."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 30, 16, 'When he had taken him down, they were spread out all over the ground, eating and drinking and dancing, because of the great amount of spoil they had taken from the land of the Philistines and from the land of Judah.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 30, 17, 'David attacked them from twilight until the evening of the next day. Not one of them escaped, except four hundred young men, who mounted camels and fled.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 30, 18, 'David recovered all that the Amalekites had taken; and David rescued his two wives.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 30, 19, 'Nothing was missing, whether small or great, sons or daughters, spoil or anything that had been taken; David brought back everything.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 30, 20, 'David also captured all the flocks and herds, which were driven ahead of the other cattle; people said, "This is David"s spoil."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 30, 21, 'Then David came to the two hundred men who had been too exhausted to follow David, and who had been left at the Wadi Besor. They went out to meet David and to meet the people who were with him. When David drew near to the people he saluted them.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 30, 22, 'Then all the corrupt and worthless fellows among the men who had gone with David said, "Because they did not go with us, we will not give them any of the spoil that we have recovered, except that each man may take his wife and children, and leave."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 30, 23, 'But David said, "You shall not do so, my brothers, with what the LORD has given us; he has preserved us and handed over to us the raiding party that attacked us.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 30, 24, 'Who would listen to you in this matter? For the share of the one who goes down into the battle shall be the same as the share of the one who stays by the baggage; they shall share alike."', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 30, 25, 'From that day forward he made it a statute and an ordinance for Israel; it continues to the present day.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 30, 26, 'When David came to Ziklag, he sent part of the spoil to his friends, the elders of Judah, saying, "Here is a present for you from the spoil of the enemies of the LORD";', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 30, 27, 'it was for those in Bethel, in Ramoth of the Negeb, in Jattir,', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 30, 28, 'in Aroer, in Siphmoth, in Eshtemoa,', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 30, 29, 'in Racal, in the towns of the Jerahmeelites, in the towns of the Kenites,', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 30, 30, 'in Hormah, in Bor-ashan, in Athach,', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 30, 31, 'in Hebron, all the places where David and his men had roamed.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(9, '1 Sam', '1 Samuel', 31, 1, 'Now the Philistines fought against Israel; and the men of Israel fled before the Philistines, and many fell on Mount Gilboa.', 'en', 'NRSV-CE', 'The Death of Saul and His Sons'),
(9, '1 Sam', '1 Samuel', 31, 2, 'The Philistines overtook Saul and his sons; and the Philistines killed Jonathan and Abinadab and Malchishua, the sons of Saul.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 31, 3, 'The battle pressed hard upon Saul; the archers found him, and he was badly wounded by them.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 31, 4, 'Then Saul said to his armor-bearer, "Draw your sword and thrust me through with it, so that these uncircumcised may not come and thrust me through, and make sport of me." But his armor-bearer was unwilling; for he was terrified. So Saul took his own sword and fell upon it.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 31, 5, 'When his armor-bearer saw that Saul was dead, he also fell upon his sword and died with him.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 31, 6, 'So Saul and his three sons and his armor-bearer and all his men died together on the same day.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 31, 7, 'When the men of Israel who were on the other side of the valley and those beyond the Jordan saw that the men of Israel had fled and that Saul and his sons were dead, they forsook their towns and fled; and the Philistines came and occupied them.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 31, 8, 'The next day, when the Philistines came to strip the dead, they found Saul and his three sons fallen on Mount Gilboa.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 31, 9, 'They cut off his head, stripped off his armor, and sent messengers throughout the land of the Philistines to carry the good news to the houses of their idols and to the people.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 31, 10, 'They put his armor in the temple of Astarte; and they fastened his body to the wall of Beth-shan.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 31, 11, 'But when the inhabitants of Jabesh-gilead heard what the Philistines had done to Saul,', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 31, 12, 'all the valiant men set out, traveled all night long, and took the body of Saul and the bodies of his sons from the wall of Beth-shan. They came to Jabesh and burned them there.', 'en', 'NRSV-CE', NULL),
(9, '1 Sam', '1 Samuel', 31, 13, 'Then they took their bones and buried them under the tamarisk tree in Jabesh, and fasted seven days.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(10, '2 Sam', '2 Samuel', 1, 1, 'After the death of Saul, when David had returned from defeating the Amalekites, David remained two days in Ziklag.', 'en', 'NRSV-CE', 'David Mourns for Saul and Jonathan'),
(10, '2 Sam', '2 Samuel', 1, 2, 'On the third day, a man came from Saul"s camp, with his clothes torn and dirt on his head. When he came to David, he fell to the ground and did obeisance.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 1, 3, 'David said to him, "Where have you come from?" He said to him, "I have escaped from the camp of Israel."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 1, 4, 'David said to him, "How did things go? Tell me!" He answered, "The army fled from the battle, but also many of the army fell and died; and Saul and his son Jonathan also died."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 1, 5, 'Then David asked the young man who was reporting to him, "How do you know that Saul and his son Jonathan died?"', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 1, 6, 'The young man reporting to him said, "I happened to be on Mount Gilboa; and there was Saul leaning on his spear, while the chariots and the horsemen drew close to him.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 1, 7, 'When he looked behind him, he saw me, and called to me. I answered, "Here sir."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 1, 8, 'And he said to me, "Who are you?" I answered him, "I am an Amalekite."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 1, 9, 'He said to me, "Come, stand over me and kill me; for convulsions have seized me, and yet my life still lingers."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 1, 10, 'So I stood over him, and killed him, for I knew that he could not live after he had fallen. I took the crown that was on his head and the armlet that was on his arm, and I have brought them here to my lord."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 1, 11, 'Then David took hold of his clothes and tore them; and all the men who were with him did the same.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 1, 12, 'They mourned and wept, and fasted until evening for Saul and for his son Jonathan, and for the army of the LORD and for the house of Israel, because they had fallen by the sword.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 1, 13, 'David said to the young man who had reported to him, "Where do you come from?" He answered, "I am the son of a resident alien, an Amalekite."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 1, 14, 'David said to him, "Were you not afraid to lift your hand to destroy the LORD"s anointed?"', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 1, 15, 'Then David called one of the young men and said, "Come here and strike him down." So he struck him down and he died.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 1, 16, 'David said to him, "Your blood be on your head; for your own mouth has testified against you, saying, "I have killed the LORD"s anointed.""', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 1, 17, 'David intoned this lamentation over Saul and his son Jonathan.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 1, 18, '(He ordered that The Song of the Bow be taught to the people of Judah; it is written in the Book of Jashar.) He said:', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 1, 19, 'Your glory, O Israel, lies slain upon your high places!  
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(10, '2 Sam', '2 Samuel', 2, 1, 'After this David inquired of the LORD, "Shall I go up into any of the cities of Judah?" The LORD said to him, "Go up." David said, "To which shall I go up?" He said, "To Hebron."', 'en', 'NRSV-CE', 'David Anointed King of Judah'),
(10, '2 Sam', '2 Samuel', 2, 2, 'So David went up there, along with his two wives, Ahinoam of Jezreel, and Abigail the widow of Nabal of Carmel.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 2, 3, 'David brought up the men who were with him, every one with his household; and they settled in the towns of Hebron.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 2, 4, 'Then the people of Judah came, and there they anointed David king over the house of Judah.
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(10, '2 Sam', '2 Samuel', 3, 1, 'There was a long war between the house of Saul and the house of David; David grew stronger and stronger, while the house of Saul became weaker and weaker.', 'en', 'NRSV-CE', 'Abner Defects to David'),
(10, '2 Sam', '2 Samuel', 3, 2, 'Sons were born to David at Hebron: his firstborn was Amnon, of Ahinoam of Jezreel;', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 3, 3, 'his second, Chileab, of Abigail the widow of Nabal of Carmel; the third, Absalom son of Maacah, daughter of King Talmai of Geshur;', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 3, 4, 'the fourth, Adonijah son of Haggith; the fifth, Shephatiah son of Abital;', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 3, 5, 'and the sixth, Ithream, of David"s wife Eglah. These were born to David in Hebron.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 3, 6, 'While there was war between the house of Saul and the house of David, Abner was making himself strong in the house of Saul.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 3, 7, 'Now Saul had a concubine whose name was Rizpah daughter of Aiah. And Ishbaal said to Abner, "Why have you gone in to my father"s concubine?"', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 3, 8, 'The words of Ishbaal made Abner very angry; he said, "Am I a dog"s head for Judah? Today I keep showing loyalty to the house of your father Saul, to his brothers, and to his friends, and have not given you into the hand of David; and yet you charge me now with a crime concerning this woman.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 3, 9, 'So may God do to Abner and so may he add to it! For just what the LORD has sworn to David, that will I accomplish for him,', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 3, 10, 'to transfer the kingdom from the house of Saul, and set up the throne of David over Israel and over Judah, from Dan to Beer-sheba."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 3, 11, 'And Ishbaal could not answer Abner another word, because he feared him.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 3, 12, 'Abner sent messengers to David at Hebron, saying, "To whom does the land belong? Make your covenant with me, and I will give you my support to bring all Israel over to you."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 3, 13, 'He said, "Good; I will make a covenant with you. But one thing I require of you: you shall never appear in my presence unless you bring Saul"s daughter Michal when you come to see me."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 3, 14, 'Then David sent messengers to Saul"s son Ishbaal, saying, "Give me my wife Michal, to whom I became engaged at the price of one hundred foreskins of the Philistines."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 3, 15, 'Ishbaal sent and took her from her husband Paltiel the son of Laish.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 3, 16, 'But her husband went with her, weeping as he walked behind her all the way to Bahurim. Then Abner said to him, "Go back home!" So he went back.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 3, 17, 'Abner sent word to the elders of Israel, saying, "For some time past you have been seeking David as king over you.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 3, 18, 'Now then bring it about; for the LORD has promised David: Through my servant David I will save my people Israel from the hand of the Philistines, and from all their enemies."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 3, 19, 'Abner also spoke directly to the Benjaminites; then Abner went to tell David at Hebron all that Israel and the whole house of Benjamin were ready to do.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 3, 20, 'When Abner came with twenty men to David at Hebron, David made a feast for Abner and the men who were with him.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 3, 21, 'Abner said to David, "Let me go and rally all Israel to my lord the king, in order that they may make a covenant with you, and that you may reign over all that your heart desires." So David dismissed Abner, and he went away in peace.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 3, 22, 'Just then the servants of David arrived with Joab from a raid, bringing much spoil with them. But Abner was not with David at Hebron, for David had dismissed him, and he had gone away in peace.', 'en', 'NRSV-CE', 'Abner Is Killed by Joab'),
(10, '2 Sam', '2 Samuel', 3, 23, 'When Joab and all the army that was with him came, it was told Joab, "Abner son of Ner came to the king, and he has dismissed him, and he has gone away in peace."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 3, 24, 'Then Joab went to the king and said, "What have you done? Abner came to you; why did you dismiss him, so that he got away?', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 3, 25, 'You know that Abner son of Ner came to deceive you, and to learn your comings and goings and to learn all that you are doing."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 3, 26, 'When Joab came out from David"s presence, he sent messengers after Abner, and they brought him back from the cistern of Sirah; but David did not know about it.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 3, 27, 'When Abner returned to Hebron, Joab took him aside in the gateway to speak with him privately, and there he stabbed him in the stomach. So he died for shedding the blood of Asahel, Joab"s brother.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 3, 28, 'Afterward, when David heard of it, he said, "I and my kingdom are forever guiltless before the LORD for the blood of Abner son of Ner.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 3, 29, 'May the guilt fall on the head of Joab, and on all his father"s house; and may the house of Joab never be without one who has a discharge, or who is leprous, or who holds a spindle, or who falls by the sword, or who lacks food!"', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 3, 30, 'So Joab and his brother Abishai murdered Abner because he had killed their brother Asahel in the battle at Gibeon.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 3, 31, 'Then David said to Joab and to all the people who were with him, "Tear your clothes, and put on sackcloth, and mourn over Abner." And King David followed the bier.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 3, 32, 'They buried Abner at Hebron. The king lifted up his voice and wept at the grave of Abner, and all the people wept.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 3, 33, 'The king lamented for Abner, saying,
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(10, '2 Sam', '2 Samuel', 4, 1, 'When Saul"s son Ishbaal heard that Abner had died at Hebron, his courage failed, and all Israel was dismayed.', 'en', 'NRSV-CE', 'Ishbaal Assassinated'),
(10, '2 Sam', '2 Samuel', 4, 2, 'Saul"s son had two captains of raiding bands; the name of the one was Baanah, and the name of the other Rechab. They were sons of Rimmon a Benjaminite from Beeroth--for Beeroth is considered to belong to Benjamin.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 4, 3, '(Now the people of Beeroth had fled to Gittaim and are there as resident aliens to this day).', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 4, 4, 'Saul"s son Jonathan had a son who was crippled in his feet. He was five years old when the news about Saul and Jonathan came from Jezreel. His nurse picked him up and fled; and, in her haste to flee, it happened that he fell and became lame. His name was Mephibosheth.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 4, 5, 'Now the sons of Rimmon the Beerothite, Rechab and Baanah, set out, and about the heat of the day they came to the house of Ishbaal, while he was taking his noonday rest.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 4, 6, 'They came inside the house as though to take wheat, and they struck him in the stomach; then Rechab and his brother Baanah escaped.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 4, 7, 'Now they had come into the house while he was lying on his couch in his bedchamber; they attacked him, killed him, and beheaded him. Then they took his head and traveled by way of the Arabah all night long.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 4, 8, 'They brought the head of Ishbaal to David at Hebron and said to the king, "Here is the head of Ishbaal, son of Saul, your enemy, who sought your life; the LORD has avenged my lord the king this day on Saul and on his offspring."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 4, 9, 'David answered Rechab and his brother Baanah, the sons of Rimmon the Beerothite, "As the LORD lives, who has redeemed my life out of every adversity,', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 4, 10, 'when the one who told me, "See, Saul is dead," thought he was bringing good news, I seized him and killed him at Ziklag--this was the reward I gave him for his news.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 4, 11, 'How much more then, when wicked men have killed a righteous man on his bed in his own house! And now shall I not require his blood at your hand, and destroy you from the earth?"', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 4, 12, 'So David commanded the young men, and they killed them; they cut off their hands and feet, and hung their bodies beside the pool at Hebron. But the head of Ishbaal they took and buried in the tomb of Abner at Hebron.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(10, '2 Sam', '2 Samuel', 5, 1, 'Then all the tribes of Israel came to David at Hebron, and said, "Look, we are your bone and flesh.', 'en', 'NRSV-CE', 'David Anointed King of All Israel'),
(10, '2 Sam', '2 Samuel', 5, 2, 'For some time, while Saul was king over us, it was you who led out Israel and brought it in. The LORD said to you: It is you who shall be shepherd of my people Israel, you who shall be ruler over Israel."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 5, 3, 'So all the elders of Israel came to the king at Hebron; and King David made a covenant with them at Hebron before the LORD, and they anointed David king over Israel.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 5, 4, 'David was thirty years old when he began to reign, and he reigned forty years.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 5, 5, 'At Hebron he reigned over Judah seven years and six months; and at Jerusalem he reigned over all Israel and Judah thirty-three years.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 5, 6, 'The king and his men marched to Jerusalem against the Jebusites, the inhabitants of the land, who said to David, "You will not come in here, even the blind and the lame will turn you back"--thinking, "David cannot come in here."', 'en', 'NRSV-CE', 'Jerusalem Made Capital of the United Kingdom'),
(10, '2 Sam', '2 Samuel', 5, 7, 'Nevertheless David took the stronghold of Zion, which is now the city of David.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 5, 8, 'David had said on that day, "Whoever would strike down the Jebusites, let him get up the water shaft to attack the lame and the blind, those whom David hates." Therefore it is said, "The blind and the lame shall not come into the house."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 5, 9, 'David occupied the stronghold, and named it the city of David. David built the city all around from the Millo inward.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 5, 10, 'And David became greater and greater, for the LORD, the God of hosts, was with him.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 5, 11, 'King Hiram of Tyre sent messengers to David, along with cedar trees, and carpenters and masons who built David a house.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 5, 12, 'David then perceived that the LORD had established him king over Israel, and that he had exalted his kingdom for the sake of his people Israel.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 5, 13, 'In Jerusalem, after he came from Hebron, David took more concubines and wives; and more sons and daughters were born to David.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 5, 14, 'These are the names of those who were born to him in Jerusalem: Shammua, Shobab, Nathan, Solomon,', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 5, 15, 'Ibhar, Elishua, Nepheg, Japhia,', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 5, 16, 'Elishama, Eliada, and Eliphelet.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 5, 17, 'When the Philistines heard that David had been anointed king over Israel, all the Philistines went up in search of David; but David heard about it and went down to the stronghold.', 'en', 'NRSV-CE', 'Philistine Attack Repulsed'),
(10, '2 Sam', '2 Samuel', 5, 18, 'Now the Philistines had come and spread out in the valley of Rephaim.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 5, 19, 'David inquired of the LORD, "Shall I go up against the Philistines? Will you give them into my hand?" The LORD said to David, "Go up; for I will certainly give the Philistines into your hand."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 5, 20, 'So David came to Baal-perazim, and David defeated them there. He said, "The LORD has burst forth against my enemies before me, like a bursting flood." Therefore that place is called Baal-perazim.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 5, 21, 'The Philistines abandoned their idols there, and David and his men carried them away.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 5, 22, 'Once again the Philistines came up, and were spread out in the valley of Rephaim.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 5, 23, 'When David inquired of the LORD, he said, "You shall not go up; go around to their rear, and come upon them opposite the balsam trees.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 5, 24, 'When you hear the sound of marching in the tops of the balsam trees, then be on the alert; for then the LORD has gone out before you to strike down the army of the Philistines."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 5, 25, 'David did just as the LORD had commanded him; and he struck down the Philistines from Geba all the way to Gezer.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(10, '2 Sam', '2 Samuel', 6, 1, 'David again gathered all the chosen men of Israel, thirty thousand.', 'en', 'NRSV-CE', 'David Brings the Ark to Jerusalem'),
(10, '2 Sam', '2 Samuel', 6, 2, 'David and all the people with him set out and went from Baale-judah, to bring up from there the ark of God, which is called by the name of the LORD of hosts who is enthroned on the cherubim.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 6, 3, 'They carried the ark of God on a new cart, and brought it out of the house of Abinadab, which was on the hill. Uzzah and Ahio, the sons of Abinadab, were driving the new cart', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 6, 4, 'with the ark of God; and Ahio went in front of the ark.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 6, 5, 'David and all the house of Israel were dancing before the LORD with all their might, with songs and lyres and harps and tambourines and castanets and cymbals.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 6, 6, 'When they came to the threshing floor of Nacon, Uzzah reached out his hand to the ark of God and took hold of it, for the oxen shook it.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 6, 7, 'The anger of the LORD was kindled against Uzzah; and God struck him there because he reached out his hand to the ark; and he died there beside the ark of God.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 6, 8, 'David was angry because the LORD had burst forth with an outburst upon Uzzah; so that place is called Perez-uzzah, to this day.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 6, 9, 'David was afraid of the LORD that day; he said, "How can the ark of the LORD come into my care?"', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 6, 10, 'So David was unwilling to take the ark of the LORD into his care in the city of David; instead David took it to the house of Obed-edom the Gittite.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 6, 11, 'The ark of the LORD remained in the house of Obed-edom the Gittite three months; and the LORD blessed Obed-edom and all his household.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 6, 12, 'It was told King David, "The LORD has blessed the household of Obed-edom and all that belongs to him, because of the ark of God." So David went and brought up the ark of God from the house of Obed-edom to the city of David with rejoicing;', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 6, 13, 'and when those who bore the ark of the LORD had gone six paces, he sacrificed an ox and a fatling.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 6, 14, 'David danced before the LORD with all his might; David was girded with a linen ephod.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 6, 15, 'So David and all the house of Israel brought up the ark of the LORD with shouting, and with the sound of the trumpet.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 6, 16, 'As the ark of the LORD came into the city of David, Michal daughter of Saul looked out of the window, and saw King David leaping and dancing before the LORD; and she despised him in her heart.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 6, 17, 'They brought in the ark of the LORD, and set it in its place, inside the tent that David had pitched for it; and David offered burnt offerings and offerings of well-being before the LORD.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 6, 18, 'When David had finished offering the burnt offerings and the offerings of well-being, he blessed the people in the name of the LORD of hosts,', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 6, 19, 'and distributed food among all the people, the whole multitude of Israel, both men and women, to each a cake of bread, a portion of meat, and a cake of raisins. Then all the people went back to their homes.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 6, 20, 'David returned to bless his household. But Michal the daughter of Saul came out to meet David, and said, "How the king of Israel honored himself today, uncovering himself today before the eyes of his servants" maids, as any vulgar fellow might shamelessly uncover himself!"', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 6, 21, 'David said to Michal, "It was before the LORD, who chose me in place of your father and all his household, to appoint me as prince over Israel, the people of the LORD, that I have danced before the LORD.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 6, 22, 'I will make myself yet more contemptible than this, and I will be abased in my own eyes; but by the maids of whom you have spoken, by them I shall be held in honor."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 6, 23, 'And Michal the daughter of Saul had no child to the day of her death.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(10, '2 Sam', '2 Samuel', 7, 1, 'Now when the king was settled in his house, and the LORD had given him rest from all his enemies around him,', 'en', 'NRSV-CE', 'God"s Covenant with David'),
(10, '2 Sam', '2 Samuel', 7, 2, 'the king said to the prophet Nathan, "See now, I am living in a house of cedar, but the ark of God stays in a tent."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 7, 3, 'Nathan said to the king, "Go, do all that you have in mind; for the LORD is with you."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 7, 4, 'But that same night the word of the LORD came to Nathan:', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 7, 5, 'Go and tell my servant David: Thus says the LORD: Are you the one to build me a house to live in?', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 7, 6, 'I have not lived in a house since the day I brought up the people of Israel from Egypt to this day, but I have been moving about in a tent and a tabernacle.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 7, 7, 'Wherever I have moved about among all the people of Israel, did I ever speak a word with any of the tribal leaders of Israel, whom I commanded to shepherd my people Israel, saying, "Why have you not built me a house of cedar?"', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 7, 8, 'Now therefore thus you shall say to my servant David: Thus says the LORD of hosts: I took you from the pasture, from following the sheep to be prince over my people Israel;', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 7, 9, 'and I have been with you wherever you went, and have cut off all your enemies from before you; and I will make for you a great name, like the name of the great ones of the earth.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 7, 10, 'And I will appoint a place for my people Israel and will plant them, so that they may live in their own place, and be disturbed no more; and evildoers shall afflict them no more, as formerly,', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 7, 11, 'from the time that I appointed judges over my people Israel; and I will give you rest from all your enemies. Moreover the LORD declares to you that the LORD will make you a house.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 7, 12, 'When your days are fulfilled and you lie down with your ancestors, I will raise up your offspring after you, who shall come forth from your body, and I will establish his kingdom.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 7, 13, 'He shall build a house for my name, and I will establish the throne of his kingdom forever.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 7, 14, 'I will be a father to him, and he shall be a son to me. When he commits iniquity, I will punish him with a rod such as mortals use, with blows inflicted by human beings.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 7, 15, 'But I will not take my steadfast love from him, as I took it from Saul, whom I put away from before you.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 7, 16, 'Your house and your kingdom shall be made sure forever before me; your throne shall be established forever.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 7, 17, 'In accordance with all these words and with all this vision, Nathan spoke to David.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 7, 18, 'Then King David went in and sat before the LORD, and said, "Who am I, O Lord God, and what is my house, that you have brought me thus far?', 'en', 'NRSV-CE', 'David"s Prayer'),
(10, '2 Sam', '2 Samuel', 7, 19, 'And yet this was a small thing in your eyes, O Lord God; you have spoken also of your servant"s house for a great while to come. May this be instruction for the people, O Lord God!', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 7, 20, 'And what more can David say to you? For you know your servant, O Lord God!', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 7, 21, 'Because of your promise, and according to your own heart, you have wrought all this greatness, so that your servant may know it.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 7, 22, 'Therefore you are great, O LORD God; for there is no one like you, and there is no God besides you, according to all that we have heard with our ears.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 7, 23, 'Who is like your people, like Israel? Is there another nation on earth whose God went to redeem it as a people, and to make a name for himself, doing great and awesome things for them, by driving out before his people nations and their gods?', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 7, 24, 'And you established your people Israel for yourself to be your people forever; and you, O LORD, became their God.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 7, 25, 'And now, O LORD God, as for the word that you have spoken concerning your servant and concerning his house, confirm it forever; do as you have promised.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 7, 26, 'Thus your name will be magnified forever in the saying, "The LORD of hosts is God over Israel"; and the house of your servant David will be established before you.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 7, 27, 'For you, O LORD of hosts, the God of Israel, have made this revelation to your servant, saying, "I will build you a house"; therefore your servant has found courage to pray this prayer to you.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 7, 28, 'And now, O Lord God, you are God, and your words are true, and you have promised this good thing to your servant;', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 7, 29, 'now therefore may it please you to bless the house of your servant, so that it may continue forever before you; for you, O Lord God, have spoken, and with your blessing shall the house of your servant be blessed forever."', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(10, '2 Sam', '2 Samuel', 8, 1, 'Some time afterward, David attacked the Philistines and subdued them; David took Metheg-ammah out of the hand of the Philistines.', 'en', 'NRSV-CE', 'David"s Wars'),
(10, '2 Sam', '2 Samuel', 8, 2, 'He also defeated the Moabites and, making them lie down on the ground, measured them off with a cord; he measured two lengths of cord for those who were to be put to death, and one length for those who were to be spared. And the Moabites became servants to David and brought tribute.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 8, 3, 'David also struck down King Hadadezer son of Rehob of Zobah, as he went to restore his monument at the river Euphrates.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 8, 4, 'David took from him one thousand seven hundred horsemen, and twenty thousand foot soldiers. David hamstrung all the chariot horses, but left enough for a hundred chariots.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 8, 5, 'When the Arameans of Damascus came to help King Hadadezer of Zobah, David killed twenty-two thousand men of the Arameans.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 8, 6, 'Then David put garrisons among the Arameans of Damascus; and the Arameans became servants to David and brought tribute. The LORD gave victory to David wherever he went.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 8, 7, 'David took the gold shields that were carried by the servants of Hadadezer, and brought them to Jerusalem.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 8, 8, 'From Betah and from Berothai, towns of Hadadezer, King David took a great amount of bronze.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 8, 9, 'When King Toi of Hamath heard that David had defeated the whole army of Hadadezer,', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 8, 10, 'Toi sent his son Joram to King David, to greet him and to congratulate him because he had fought against Hadadezer and defeated him. Now Hadadezer had often been at war with Toi. Joram brought with him articles of silver, gold, and bronze;', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 8, 11, 'these also King David dedicated to the LORD, together with the silver and gold that he dedicated from all the nations he subdued,', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 8, 12, 'from Edom, Moab, the Ammonites, the Philistines, Amalek, and from the spoil of King Hadadezer son of Rehob of Zobah.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 8, 13, 'David won a name for himself. When he returned, he killed eighteen thousand Edomites in the Valley of Salt.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 8, 14, 'He put garrisons in Edom; throughout all Edom he put garrisons, and all the Edomites became David"s servants. And the LORD gave victory to David wherever he went.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 8, 15, 'So David reigned over all Israel; and David administered justice and equity to all his people.', 'en', 'NRSV-CE', 'David"s Officers'),
(10, '2 Sam', '2 Samuel', 8, 16, 'Joab son of Zeruiah was over the army; Jehoshaphat son of Ahilud was recorder;', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 8, 17, 'Zadok son of Ahitub and Ahimelech son of Abiathar were priests; Seraiah was secretary;', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 8, 18, 'Benaiah son of Jehoiada was over the Cherethites and the Pelethites; and David"s sons were priests.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(10, '2 Sam', '2 Samuel', 9, 1, 'David asked, "Is there still anyone left of the house of Saul to whom I may show kindness for Jonathan"s sake?"', 'en', 'NRSV-CE', 'David"s Kindness to Mephibosheth'),
(10, '2 Sam', '2 Samuel', 9, 2, 'Now there was a servant of the house of Saul whose name was Ziba, and he was summoned to David. The king said to him, "Are you Ziba?" And he said, "At your service!"', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 9, 3, 'The king said, "Is there anyone remaining of the house of Saul to whom I may show the kindness of God?" Ziba said to the king, "There remains a son of Jonathan; he is crippled in his feet."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 9, 4, 'The king said to him, "Where is he?" Ziba said to the king, "He is in the house of Machir son of Ammiel, at Lo-debar."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 9, 5, 'Then King David sent and brought him from the house of Machir son of Ammiel, at Lo-debar.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 9, 6, 'Mephibosheth son of Jonathan son of Saul came to David, and fell on his face and did obeisance. David said, "Mephibosheth!" He answered, "I am your servant."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 9, 7, 'David said to him, "Do not be afraid, for I will show you kindness for the sake of your father Jonathan; I will restore to you all the land of your grandfather Saul, and you yourself shall eat at my table always."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 9, 8, 'He did obeisance and said, "What is your servant, that you should look upon a dead dog such as I?"', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 9, 9, 'Then the king summoned Saul"s servant Ziba, and said to him, "All that belonged to Saul and to all his house I have given to your master"s grandson.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 9, 10, 'You and your sons and your servants shall till the land for him, and shall bring in the produce, so that your master"s grandson may have food to eat; but your master"s grandson Mephibosheth shall always eat at my table." Now Ziba had fifteen sons and twenty servants.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 9, 11, 'Then Ziba said to the king, "According to all that my lord the king commands his servant, so your servant will do." Mephibosheth ate at David"s table, like one of the king"s sons.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 9, 12, 'Mephibosheth had a young son whose name was Mica. And all who lived in Ziba"s house became Mephibosheth"s servants.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 9, 13, 'Mephibosheth lived in Jerusalem, for he always ate at the king"s table. Now he was lame in both his feet.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(10, '2 Sam', '2 Samuel', 10, 1, 'Some time afterward, the king of the Ammonites died, and his son Hanun succeeded him.', 'en', 'NRSV-CE', 'The Ammonites and Arameans Are Defeated'),
(10, '2 Sam', '2 Samuel', 10, 2, 'David said, "I will deal loyally with Hanun son of Nahash, just as his father dealt loyally with me." So David sent envoys to console him concerning his father. When David"s envoys came into the land of the Ammonites,', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 10, 3, 'the princes of the Ammonites said to their lord Hanun, "Do you really think that David is honoring your father just because he has sent messengers with condolences to you? Has not David sent his envoys to you to search the city, to spy it out, and to overthrow it?"', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 10, 4, 'So Hanun seized David"s envoys, shaved off half the beard of each, cut off their garments in the middle at their hips, and sent them away.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 10, 5, 'When David was told, he sent to meet them, for the men were greatly ashamed. The king said, "Remain at Jericho until your beards have grown, and then return."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 10, 6, 'When the Ammonites saw that they had become odious to David, the Ammonites sent and hired the Arameans of Beth-rehob and the Arameans of Zobah, twenty thousand foot soldiers, as well as the king of Maacah, one thousand men, and the men of Tob, twelve thousand men.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 10, 7, 'When David heard of it, he sent Joab and all the army with the warriors.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 10, 8, 'The Ammonites came out and drew up in battle array at the entrance of the gate; but the Arameans of Zobah and of Rehob, and the men of Tob and Maacah, were by themselves in the open country.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 10, 9, 'When Joab saw that the battle was set against him both in front and in the rear, he chose some of the picked men of Israel, and arrayed them against the Arameans;', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 10, 10, 'the rest of his men he put in the charge of his brother Abishai, and he arrayed them against the Ammonites.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 10, 11, 'He said, "If the Arameans are too strong for me, then you shall help me; but if the Ammonites are too strong for you, then I will come and help you.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 10, 12, 'Be strong, and let us be courageous for the sake of our people, and for the cities of our God; and may the LORD do what seems good to him."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 10, 13, 'So Joab and the people who were with him moved forward into battle against the Arameans; and they fled before him.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 10, 14, 'When the Ammonites saw that the Arameans fled, they likewise fled before Abishai, and entered the city. Then Joab returned from fighting against the Ammonites, and came to Jerusalem.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 10, 15, 'But when the Arameans saw that they had been defeated by Israel, they gathered themselves together.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 10, 16, 'Hadadezer sent and brought out the Arameans who were beyond the Euphrates; and they came to Helam, with Shobach the commander of the army of Hadadezer at their head.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 10, 17, 'When it was told David, he gathered all Israel together, and crossed the Jordan, and came to Helam. The Arameans arrayed themselves against David and fought with him.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 10, 18, 'The Arameans fled before Israel; and David killed of the Arameans seven hundred chariot teams, and forty thousand horsemen, and wounded Shobach the commander of their army, so that he died there.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 10, 19, 'When all the kings who were servants of Hadadezer saw that they had been defeated by Israel, they made peace with Israel, and became subject to them. So the Arameans were afraid to help the Ammonites any more.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(10, '2 Sam', '2 Samuel', 11, 1, 'In the spring of the year, the time when kings go out to battle, David sent Joab with his officers and all Israel with him; they ravaged the Ammonites, and besieged Rabbah. But David remained at Jerusalem.', 'en', 'NRSV-CE', 'David Commits Adultery with Bathsheba'),
(10, '2 Sam', '2 Samuel', 11, 2, 'It happened, late one afternoon, when David rose from his couch and was walking about on the roof of the king"s house, that he saw from the roof a woman bathing; the woman was very beautiful.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 11, 3, 'David sent someone to inquire about the woman. It was reported, "This is Bathsheba daughter of Eliam, the wife of Uriah the Hittite."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 11, 4, 'So David sent messengers to get her, and she came to him, and he lay with her. (Now she was purifying herself after her period.) Then she returned to her house.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 11, 5, 'The woman conceived; and she sent and told David, "I am pregnant."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 11, 6, 'So David sent word to Joab, "Send me Uriah the Hittite." And Joab sent Uriah to David.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 11, 7, 'When Uriah came to him, David asked how Joab and the people fared, and how the war was going.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 11, 8, 'Then David said to Uriah, "Go down to your house, and wash your feet." Uriah went out of the king"s house, and there followed him a present from the king.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 11, 9, 'But Uriah slept at the entrance of the king"s house with all the servants of his lord, and did not go down to his house.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 11, 10, 'When they told David, "Uriah did not go down to his house," David said to Uriah, "You have just come from a journey. Why did you not go down to your house?"', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 11, 11, 'Uriah said to David, "The ark and Israel and Judah remain in booths; and my lord Joab and the servants of my lord are camping in the open field; shall I then go to my house, to eat and to drink, and to lie with my wife? As you live, and as your soul lives, I will not do such a thing."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 11, 12, 'Then David said to Uriah, "Remain here today also, and tomorrow I will send you back." So Uriah remained in Jerusalem that day. On the next day,', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 11, 13, 'David invited him to eat and drink in his presence and made him drunk; and in the evening he went out to lie on his couch with the servants of his lord, but he did not go down to his house.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 11, 14, 'In the morning David wrote a letter to Joab, and sent it by the hand of Uriah.', 'en', 'NRSV-CE', 'David Has Uriah Killed'),
(10, '2 Sam', '2 Samuel', 11, 15, 'In the letter he wrote, "Set Uriah in the forefront of the hardest fighting, and then draw back from him, so that he may be struck down and die."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 11, 16, 'As Joab was besieging the city, he assigned Uriah to the place where he knew there were valiant warriors.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 11, 17, 'The men of the city came out and fought with Joab; and some of the servants of David among the people fell. Uriah the Hittite was killed as well.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 11, 18, 'Then Joab sent and told David all the news about the fighting;', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 11, 19, 'and he instructed the messenger, "When you have finished telling the king all the news about the fighting,', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 11, 20, 'then, if the king"s anger rises, and if he says to you, "Why did you go so near the city to fight? Did you not know that they would shoot from the wall?', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 11, 21, 'Who killed Abimelech son of Jerubbaal? Did not a woman throw an upper millstone on him from the wall, so that he died at Thebez? Why did you go so near the wall?" then you shall say, "Your servant Uriah the Hittite is dead too.""', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 11, 22, 'So the messenger went, and came and told David all that Joab had sent him to tell.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 11, 23, 'The messenger said to David, "The men gained an advantage over us, and came out against us in the field; but we drove them back to the entrance of the gate.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 11, 24, 'Then the archers shot at your servants from the wall; some of the king"s servants are dead; and your servant Uriah the Hittite is dead also."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 11, 25, 'David said to the messenger, "Thus you shall say to Joab, "Do not let this matter trouble you, for the sword devours now one and now another; press your attack on the city, and overthrow it." And encourage him."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 11, 26, 'When the wife of Uriah heard that her husband was dead, she made lamentation for him.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 11, 27, 'When the mourning was over, David sent and brought her to his house, and she became his wife, and bore him a son.
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(10, '2 Sam', '2 Samuel', 12, 1, 'and the LORD sent Nathan to David. He came to him, and said to him, "There were two men in a certain city, the one rich and the other poor.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 12, 2, 'The rich man had very many flocks and herds;', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 12, 3, 'but the poor man had nothing but one little ewe lamb, which he had bought. He brought it up, and it grew up with him and with his children; it used to eat of his meager fare, and drink from his cup, and lie in his bosom, and it was like a daughter to him.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 12, 4, 'Now there came a traveler to the rich man, and he was loath to take one of his own flock or herd to prepare for the wayfarer who had come to him, but he took the poor man"s lamb, and prepared that for the guest who had come to him."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 12, 5, 'Then David"s anger was greatly kindled against the man. He said to Nathan, "As the LORD lives, the man who has done this deserves to die;', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 12, 6, 'he shall restore the lamb fourfold, because he did this thing, and because he had no pity."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 12, 7, 'Nathan said to David, "You are the man! Thus says the LORD, the God of Israel: I anointed you king over Israel, and I rescued you from the hand of Saul;', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 12, 8, 'I gave you your master"s house, and your master"s wives into your bosom, and gave you the house of Israel and of Judah; and if that had been too little, I would have added as much more.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 12, 9, 'Why have you despised the word of the LORD, to do what is evil in his sight? You have struck down Uriah the Hittite with the sword, and have taken his wife to be your wife, and have killed him with the sword of the Ammonites.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 12, 10, 'Now therefore the sword shall never depart from your house, for you have despised me, and have taken the wife of Uriah the Hittite to be your wife.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 12, 11, 'Thus says the LORD: I will raise up trouble against you from within your own house; and I will take your wives before your eyes, and give them to your neighbor, and he shall lie with your wives in the sight of this very sun.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 12, 12, 'For you did it secretly; but I will do this thing before all Israel, and before the sun."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 12, 13, 'David said to Nathan, "I have sinned against the LORD." Nathan said to David, "Now the LORD has put away your sin; you shall not die.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 12, 14, 'Nevertheless, because by this deed you have utterly scorned the LORD, the child that is born to you shall die."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 12, 15, 'Then Nathan went to his house.
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(10, '2 Sam', '2 Samuel', 13, 1, 'Some time passed. David"s son Absalom had a beautiful sister whose name was Tamar; and David"s son Amnon fell in love with her.', 'en', 'NRSV-CE', 'Amnon and Tamar'),
(10, '2 Sam', '2 Samuel', 13, 2, 'Amnon was so tormented that he made himself ill because of his sister Tamar, for she was a virgin and it seemed impossible to Amnon to do anything to her.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 13, 3, 'But Amnon had a friend whose name was Jonadab, the son of David"s brother Shimeah; and Jonadab was a very crafty man.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 13, 4, 'He said to him, "O son of the king, why are you so haggard morning after morning? Will you not tell me?" Amnon said to him, "I love Tamar, my brother Absalom"s sister."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 13, 5, 'Jonadab said to him, "Lie down on your bed, and pretend to be ill; and when your father comes to see you, say to him, "Let my sister Tamar come and give me something to eat, and prepare the food in my sight, so that I may see it and eat it from her hand.""', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 13, 6, 'So Amnon lay down, and pretended to be ill; and when the king came to see him, Amnon said to the king, "Please let my sister Tamar come and make a couple of cakes in my sight, so that I may eat from her hand."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 13, 7, 'Then David sent home to Tamar, saying, "Go to your brother Amnon"s house, and prepare food for him."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 13, 8, 'So Tamar went to her brother Amnon"s house, where he was lying down. She took dough, kneaded it, made cakes in his sight, and baked the cakes.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 13, 9, 'Then she took the pan and set them out before him, but he refused to eat. Amnon said, "Send out everyone from me." So everyone went out from him.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 13, 10, 'Then Amnon said to Tamar, "Bring the food into the chamber, so that I may eat from your hand." So Tamar took the cakes she had made, and brought them into the chamber to Amnon her brother.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 13, 11, 'But when she brought them near him to eat, he took hold of her, and said to her, "Come, lie with me, my sister."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 13, 12, 'She answered him, "No, my brother, do not force me; for such a thing is not done in Israel; do not do anything so vile!', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 13, 13, 'As for me, where could I carry my shame? And as for you, you would be as one of the scoundrels in Israel. Now therefore, I beg you, speak to the king; for he will not withhold me from you."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 13, 14, 'But he would not listen to her; and being stronger than she, he forced her and lay with her.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 13, 15, 'Then Amnon was seized with a very great loathing for her; indeed, his loathing was even greater than the lust he had felt for her. Amnon said to her, "Get out!"', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 13, 16, 'But she said to him, "No, my brother; for this wrong in sending me away is greater than the other that you did to me." But he would not listen to her.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 13, 17, 'He called the young man who served him and said, "Put this woman out of my presence, and bolt the door after her."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 13, 18, '(Now she was wearing a long robe with sleeves; for this is how the virgin daughters of the king were clothed in earlier times.) So his servant put her out, and bolted the door after her.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 13, 19, 'But Tamar put ashes on her head, and tore the long robe that she was wearing; she put her hand on her head, and went away, crying aloud as she went.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 13, 20, 'Her brother Absalom said to her, "Has Amnon your brother been with you? Be quiet for now, my sister; he is your brother; do not take this to heart." So Tamar remained, a desolate woman, in her brother Absalom"s house.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 13, 21, 'When King David heard of all these things, he became very angry, but he would not punish his son Amnon, because he loved him, for he was his firstborn.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 13, 22, 'But Absalom spoke to Amnon neither good nor bad; for Absalom hated Amnon, because he had raped his sister Tamar.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 13, 23, 'After two full years Absalom had sheepshearers at Baal-hazor, which is near Ephraim, and Absalom invited all the king"s sons.', 'en', 'NRSV-CE', 'Absalom Avenges the Violation of His Sister'),
(10, '2 Sam', '2 Samuel', 13, 24, 'Absalom came to the king, and said, "Your servant has sheepshearers; will the king and his servants please go with your servant?"', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 13, 25, 'But the king said to Absalom, "No, my son, let us not all go, or else we will be burdensome to you." He pressed him, but he would not go but gave him his blessing.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 13, 26, 'Then Absalom said, "If not, please let my brother Amnon go with us." The king said to him, "Why should he go with you?"', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 13, 27, 'But Absalom pressed him until he let Amnon and all the king"s sons go with him. Absalom made a feast like a king"s feast.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 13, 28, 'Then Absalom commanded his servants, "Watch when Amnon"s heart is merry with wine, and when I say to you, "Strike Amnon," then kill him. Do not be afraid; have I not myself commanded you? Be courageous and valiant."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 13, 29, 'So the servants of Absalom did to Amnon as Absalom had commanded. Then all the king"s sons rose, and each mounted his mule and fled.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 13, 30, 'While they were on the way, the report came to David that Absalom had killed all the king"s sons, and not one of them was left.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 13, 31, 'The king rose, tore his garments, and lay on the ground; and all his servants who were standing by tore their garments.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 13, 32, 'But Jonadab, the son of David"s brother Shimeah, said, "Let not my lord suppose that they have killed all the young men the king"s sons; Amnon alone is dead. This has been determined by Absalom from the day Amnon raped his sister Tamar.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 13, 33, 'Now therefore, do not let my lord the king take it to heart, as if all the king"s sons were dead; for Amnon alone is dead."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 13, 34, 'But Absalom fled. When the young man who kept watch looked up, he saw many people coming from the Horonaim road by the side of the mountain.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 13, 35, 'Jonadab said to the king, "See, the king"s sons have come; as your servant said, so it has come about."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 13, 36, 'As soon as he had finished speaking, the king"s sons arrived, and raised their voices and wept; and the king and all his servants also wept very bitterly.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 13, 37, 'But Absalom fled, and went to Talmai son of Ammihud, king of Geshur. David mourned for his son day after day.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 13, 38, 'Absalom, having fled to Geshur, stayed there three years.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 13, 39, 'And the heart of the king went out, yearning for Absalom; for he was now consoled over the death of Amnon.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(10, '2 Sam', '2 Samuel', 14, 1, 'Now Joab son of Zeruiah perceived that the king"s mind was on Absalom.', 'en', 'NRSV-CE', 'Absalom Returns to Jerusalem'),
(10, '2 Sam', '2 Samuel', 14, 2, 'Joab sent to Tekoa and brought from there a wise woman. He said to her, "Pretend to be a mourner; put on mourning garments, do not anoint yourself with oil, but behave like a woman who has been mourning many days for the dead.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 14, 3, 'Go to the king and speak to him as follows." And Joab put the words into her mouth.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 14, 4, 'When the woman of Tekoa came to the king, she fell on her face to the ground and did obeisance, and said, "Help, O king!"', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 14, 5, 'The king asked her, "What is your trouble?" She answered, "Alas, I am a widow; my husband is dead.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 14, 6, 'Your servant had two sons, and they fought with one another in the field; there was no one to part them, and one struck the other and killed him.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 14, 7, 'Now the whole family has risen against your servant. They say, "Give up the man who struck his brother, so that we may kill him for the life of his brother whom he murdered, even if we destroy the heir as well." Thus they would quench my one remaining ember, and leave to my husband neither name nor remnant on the face of the earth."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 14, 8, 'Then the king said to the woman, "Go to your house, and I will give orders concerning you."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 14, 9, 'The woman of Tekoa said to the king, "On me be the guilt, my lord the king, and on my father"s house; let the king and his throne be guiltless."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 14, 10, 'The king said, "If anyone says anything to you, bring him to me, and he shall never touch you again."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 14, 11, 'Then she said, "Please, may the king keep the LORD your God in mind, so that the avenger of blood may kill no more, and my son not be destroyed." He said, "As the LORD lives, not one hair of your son shall fall to the ground."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 14, 12, 'Then the woman said, "Please let your servant speak a word to my lord the king." He said, "Speak."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 14, 13, 'The woman said, "Why then have you planned such a thing against the people of God? For in giving this decision the king convicts himself, inasmuch as the king does not bring his banished one home again.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 14, 14, 'We must all die; we are like water spilled on the ground, which cannot be gathered up. But God will not take away a life; he will devise plans so as not to keep an outcast banished forever from his presence.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 14, 15, 'Now I have come to say this to my lord the king because the people have made me afraid; your servant thought, "I will speak to the king; it may be that the king will perform the request of his servant.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 14, 16, 'For the king will hear, and deliver his servant from the hand of the man who would cut both me and my son off from the heritage of God."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 14, 17, 'Your servant thought, "The word of my lord the king will set me at rest"; for my lord the king is like the angel of God, discerning good and evil. The LORD your God be with you!"', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 14, 18, 'Then the king answered the woman, "Do not withhold from me anything I ask you." The woman said, "Let my lord the king speak."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 14, 19, 'The king said, "Is the hand of Joab with you in all this?" The woman answered and said, "As surely as you live, my lord the king, one cannot turn right or left from anything that my lord the king has said. For it was your servant Joab who commanded me; it was he who put all these words into the mouth of your servant.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 14, 20, 'In order to change the course of affairs your servant Joab did this. But my lord has wisdom like the wisdom of the angel of God to know all things that are on the earth."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 14, 21, 'Then the king said to Joab, "Very well, I grant this; go, bring back the young man Absalom."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 14, 22, 'Joab prostrated himself with his face to the ground and did obeisance, and blessed the king; and Joab said, "Today your servant knows that I have found favor in your sight, my lord the king, in that the king has granted the request of his servant."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 14, 23, 'So Joab set off, went to Geshur, and brought Absalom to Jerusalem.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 14, 24, 'The king said, "Let him go to his own house; he is not to come into my presence." So Absalom went to his own house, and did not come into the king"s presence.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 14, 25, 'Now in all Israel there was no one to be praised so much for his beauty as Absalom; from the sole of his foot to the crown of his head there was no blemish in him.', 'en', 'NRSV-CE', 'David Forgives Absalom'),
(10, '2 Sam', '2 Samuel', 14, 26, 'When he cut the hair of his head (for at the end of every year he used to cut it; when it was heavy on him, he cut it), he weighed the hair of his head, two hundred shekels by the king"s weight.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 14, 27, 'There were born to Absalom three sons, and one daughter whose name was Tamar; she was a beautiful woman.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 14, 28, 'So Absalom lived two full years in Jerusalem, without coming into the king"s presence.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 14, 29, 'Then Absalom sent for Joab to send him to the king; but Joab would not come to him. He sent a second time, but Joab would not come.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 14, 30, 'Then he said to his servants, "Look, Joab"s field is next to mine, and he has barley there; go and set it on fire." So Absalom"s servants set the field on fire.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 14, 31, 'Then Joab rose and went to Absalom at his house, and said to him, "Why have your servants set my field on fire?"', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 14, 32, 'Absalom answered Joab, "Look, I sent word to you: Come here, that I may send you to the king with the question, "Why have I come from Geshur? It would be better for me to be there still." Now let me go into the king"s presence; if there is guilt in me, let him kill me!"', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 14, 33, 'Then Joab went to the king and told him; and he summoned Absalom. So he came to the king and prostrated himself with his face to the ground before the king; and the king kissed Absalom.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(10, '2 Sam', '2 Samuel', 15, 1, 'After this Absalom got himself a chariot and horses, and fifty men to run ahead of him.', 'en', 'NRSV-CE', 'Absalom Usurps the Throne'),
(10, '2 Sam', '2 Samuel', 15, 2, 'Absalom used to rise early and stand beside the road into the gate; and when anyone brought a suit before the king for judgment, Absalom would call out and say, "From what city are you?" When the person said, "Your servant is of such and such a tribe in Israel,"', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 15, 3, 'Absalom would say, "See, your claims are good and right; but there is no one deputed by the king to hear you."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 15, 4, 'Absalom said moreover, "If only I were judge in the land! Then all who had a suit or cause might come to me, and I would give them justice."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 15, 5, 'Whenever people came near to do obeisance to him, he would put out his hand and take hold of them, and kiss them.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 15, 6, 'Thus Absalom did to every Israelite who came to the king for judgment; so Absalom stole the hearts of the people of Israel.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 15, 7, 'At the end of four years Absalom said to the king, "Please let me go to Hebron and pay the vow that I have made to the LORD.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 15, 8, 'For your servant made a vow while I lived at Geshur in Aram: If the LORD will indeed bring me back to Jerusalem, then I will worship the LORD in Hebron."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 15, 9, 'The king said to him, "Go in peace." So he got up, and went to Hebron.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 15, 10, 'But Absalom sent secret messengers throughout all the tribes of Israel, saying, "As soon as you hear the sound of the trumpet, then shout: Absalom has become king at Hebron!"', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 15, 11, 'Two hundred men from Jerusalem went with Absalom; they were invited guests, and they went in their innocence, knowing nothing of the matter.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 15, 12, 'While Absalom was offering the sacrifices, he sent for Ahithophel the Gilonite, David"s counselor, from his city Giloh. The conspiracy grew in strength, and the people with Absalom kept increasing.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 15, 13, 'A messenger came to David, saying, "The hearts of the Israelites have gone after Absalom."', 'en', 'NRSV-CE', 'David Flees from Jerusalem'),
(10, '2 Sam', '2 Samuel', 15, 14, 'Then David said to all his officials who were with him at Jerusalem, "Get up! Let us flee, or there will be no escape for us from Absalom. Hurry, or he will soon overtake us, and bring disaster down upon us, and attack the city with the edge of the sword."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 15, 15, 'The king"s officials said to the king, "Your servants are ready to do whatever our lord the king decides."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 15, 16, 'So the king left, followed by all his household, except ten concubines whom he left behind to look after the house.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 15, 17, 'The king left, followed by all the people; and they stopped at the last house.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 15, 18, 'All his officials passed by him; and all the Cherethites, and all the Pelethites, and all the six hundred Gittites who had followed him from Gath, passed on before the king.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 15, 19, 'Then the king said to Ittai the Gittite, "Why are you also coming with us? Go back, and stay with the king; for you are a foreigner, and also an exile from your home.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 15, 20, 'You came only yesterday, and shall I today make you wander about with us, while I go wherever I can? Go back, and take your kinsfolk with you; and may the LORD show steadfast love and faithfulness to you."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 15, 21, 'But Ittai answered the king, "As the LORD lives, and as my lord the king lives, wherever my lord the king may be, whether for death or for life, there also your servant will be."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 15, 22, 'David said to Ittai, "Go then, march on." So Ittai the Gittite marched on, with all his men and all the little ones who were with him.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 15, 23, 'The whole country wept aloud as all the people passed by; the king crossed the Wadi Kidron, and all the people moved on toward the wilderness.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 15, 24, 'Abiathar came up, and Zadok also, with all the Levites, carrying the ark of the covenant of God. They set down the ark of God, until the people had all passed out of the city.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 15, 25, 'Then the king said to Zadok, "Carry the ark of God back into the city. If I find favor in the eyes of the LORD, he will bring me back and let me see both it and the place where it stays.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 15, 26, 'But if he says, "I take no pleasure in you," here I am, let him do to me what seems good to him."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 15, 27, 'The king also said to the priest Zadok, "Look, go back to the city in peace, you and Abiathar, with your two sons, Ahimaaz your son, and Jonathan son of Abiathar.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 15, 28, 'See, I will wait at the fords of the wilderness until word comes from you to inform me."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 15, 29, 'So Zadok and Abiathar carried the ark of God back to Jerusalem, and they remained there.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 15, 30, 'But David went up the ascent of the Mount of Olives, weeping as he went, with his head covered and walking barefoot; and all the people who were with him covered their heads and went up, weeping as they went.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 15, 31, 'David was told that Ahithophel was among the conspirators with Absalom. And David said, "O LORD, I pray you, turn the counsel of Ahithophel into foolishness."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 15, 32, 'When David came to the summit, where God was worshiped, Hushai the Archite came to meet him with his coat torn and earth on his head.', 'en', 'NRSV-CE', 'Hushai Becomes David"s Spy'),
(10, '2 Sam', '2 Samuel', 15, 33, 'David said to him, "If you go on with me, you will be a burden to me.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 15, 34, 'But if you return to the city and say to Absalom, "I will be your servant, O king; as I have been your father"s servant in time past, so now I will be your servant," then you will defeat for me the counsel of Ahithophel.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 15, 35, 'The priests Zadok and Abiathar will be with you there. So whatever you hear from the king"s house, tell it to the priests Zadok and Abiathar.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 15, 36, 'Their two sons are with them there, Zadok"s son Ahimaaz and Abiathar"s son Jonathan; and by them you shall report to me everything you hear."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 15, 37, 'So Hushai, David"s friend, came into the city, just as Absalom was entering Jerusalem.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(10, '2 Sam', '2 Samuel', 16, 1, 'When David had passed a little beyond the summit, Ziba the servant of Mephibosheth met him, with a couple of donkeys saddled, carrying two hundred loaves of bread, one hundred bunches of raisins, one hundred of summer fruits, and one skin of wine.', 'en', 'NRSV-CE', 'David"s Adversaries'),
(10, '2 Sam', '2 Samuel', 16, 2, 'The king said to Ziba, "Why have you brought these?" Ziba answered, "The donkeys are for the king"s household to ride, the bread and summer fruit for the young men to eat, and the wine is for those to drink who faint in the wilderness."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 16, 3, 'The king said, "And where is your master"s son?" Ziba said to the king, "He remains in Jerusalem; for he said, "Today the house of Israel will give me back my grandfather"s kingdom.""', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 16, 4, 'Then the king said to Ziba, "All that belonged to Mephibosheth is now yours." Ziba said, "I do obeisance; let me find favor in your sight, my lord the king."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 16, 5, 'When King David came to Bahurim, a man of the family of the house of Saul came out whose name was Shimei son of Gera; he came out cursing.', 'en', 'NRSV-CE', 'Shimei Curses David'),
(10, '2 Sam', '2 Samuel', 16, 6, 'He threw stones at David and at all the servants of King David; now all the people and all the warriors were on his right and on his left.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 16, 7, 'Shimei shouted while he cursed, "Out! Out! Murderer! Scoundrel!', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 16, 8, 'The LORD has avenged on all of you the blood of the house of Saul, in whose place you have reigned; and the LORD has given the kingdom into the hand of your son Absalom. See, disaster has overtaken you; for you are a man of blood."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 16, 9, 'Then Abishai son of Zeruiah said to the king, "Why should this dead dog curse my lord the king? Let me go over and take off his head."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 16, 10, 'But the king said, "What have I to do with you, you sons of Zeruiah? If he is cursing because the LORD has said to him, "Curse David," who then shall say, "Why have you done so?""', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 16, 11, 'David said to Abishai and to all his servants, "My own son seeks my life; how much more now may this Benjaminite! Let him alone, and let him curse; for the LORD has bidden him.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 16, 12, 'It may be that the LORD will look on my distress, and the LORD will repay me with good for this cursing of me today."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 16, 13, 'So David and his men went on the road, while Shimei went along on the hillside opposite him and cursed as he went, throwing stones and flinging dust at him.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 16, 14, 'The king and all the people who were with him arrived weary at the Jordan; and there he refreshed himself.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 16, 15, 'Now Absalom and all the Israelites came to Jerusalem; Ahithophel was with him.', 'en', 'NRSV-CE', 'The Counsel of Ahithophel'),
(10, '2 Sam', '2 Samuel', 16, 16, 'When Hushai the Archite, David"s friend, came to Absalom, Hushai said to Absalom, "Long live the king! Long live the king!"', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 16, 17, 'Absalom said to Hushai, "Is this your loyalty to your friend? Why did you not go with your friend?"', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 16, 18, 'Hushai said to Absalom, "No; but the one whom the LORD and this people and all the Israelites have chosen, his I will be, and with him I will remain.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 16, 19, 'Moreover, whom should I serve? Should it not be his son? Just as I have served your father, so I will serve you."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 16, 20, 'Then Absalom said to Ahithophel, "Give us your counsel; what shall we do?"', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 16, 21, 'Ahithophel said to Absalom, "Go in to your father"s concubines, the ones he has left to look after the house; and all Israel will hear that you have made yourself odious to your father, and the hands of all who are with you will be strengthened."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 16, 22, 'So they pitched a tent for Absalom upon the roof; and Absalom went in to his father"s concubines in the sight of all Israel.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 16, 23, 'Now in those days the counsel that Ahithophel gave was as if one consulted the oracle of God; so all the counsel of Ahithophel was esteemed, both by David and by Absalom.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(10, '2 Sam', '2 Samuel', 17, 1, 'Moreover Ahithophel said to Absalom, "Let me choose twelve thousand men, and I will set out and pursue David tonight.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 17, 2, 'I will come upon him while he is weary and discouraged, and throw him into a panic; and all the people who are with him will flee. I will strike down only the king,', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 17, 3, 'and I will bring all the people back to you as a bride comes home to her husband. You seek the life of only one man, and all the people will be at peace."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 17, 4, 'The advice pleased Absalom and all the elders of Israel.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 17, 5, 'Then Absalom said, "Call Hushai the Archite also, and let us hear too what he has to say."', 'en', 'NRSV-CE', 'The Counsel of Hushai'),
(10, '2 Sam', '2 Samuel', 17, 6, 'When Hushai came to Absalom, Absalom said to him, "This is what Ahithophel has said; shall we do as he advises? If not, you tell us."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 17, 7, 'Then Hushai said to Absalom, "This time the counsel that Ahithophel has given is not good."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 17, 8, 'Hushai continued, "You know that your father and his men are warriors, and that they are enraged, like a bear robbed of her cubs in the field. Besides, your father is expert in war; he will not spend the night with the troops.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 17, 9, 'Even now he has hidden himself in one of the pits, or in some other place. And when some of our troops fall at the first attack, whoever hears it will say, "There has been a slaughter among the troops who follow Absalom."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 17, 10, 'Then even the valiant warrior, whose heart is like the heart of a lion, will utterly melt with fear; for all Israel knows that your father is a warrior, and that those who are with him are valiant warriors.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 17, 11, 'But my counsel is that all Israel be gathered to you, from Dan to Beer-sheba, like the sand by the sea for multitude, and that you go to battle in person.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 17, 12, 'So we shall come upon him in whatever place he may be found, and we shall light on him as the dew falls on the ground; and he will not survive, nor will any of those with him.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 17, 13, 'If he withdraws into a city, then all Israel will bring ropes to that city, and we shall drag it into the valley, until not even a pebble is to be found there."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 17, 14, 'Absalom and all the men of Israel said, "The counsel of Hushai the Archite is better than the counsel of Ahithophel." For the LORD had ordained to defeat the good counsel of Ahithophel, so that the LORD might bring ruin on Absalom.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 17, 15, 'Then Hushai said to the priests Zadok and Abiathar, "Thus and so did Ahithophel counsel Absalom and the elders of Israel; and thus and so I have counseled.', 'en', 'NRSV-CE', 'Hushai Warns David to Escape'),
(10, '2 Sam', '2 Samuel', 17, 16, 'Therefore send quickly and tell David, "Do not lodge tonight at the fords of the wilderness, but by all means cross over; otherwise the king and all the people who are with him will be swallowed up.""', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 17, 17, 'Jonathan and Ahimaaz were waiting at En-rogel; a servant-girl used to go and tell them, and they would go and tell King David; for they could not risk being seen entering the city.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 17, 18, 'But a boy saw them, and told Absalom; so both of them went away quickly, and came to the house of a man at Bahurim, who had a well in his courtyard; and they went down into it.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 17, 19, 'The man"s wife took a covering, stretched it over the well"s mouth, and spread out grain on it; and nothing was known of it.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 17, 20, 'When Absalom"s servants came to the woman at the house, they said, "Where are Ahimaaz and Jonathan?" The woman said to them, "They have crossed over the brook of water." And when they had searched and could not find them, they returned to Jerusalem.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 17, 21, 'After they had gone, the men came up out of the well, and went and told King David. They said to David, "Go and cross the water quickly; for thus and so has Ahithophel counseled against you."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 17, 22, 'So David and all the people who were with him set out and crossed the Jordan; by daybreak not one was left who had not crossed the Jordan.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 17, 23, 'When Ahithophel saw that his counsel was not followed, he saddled his donkey and went off home to his own city. He set his house in order, and hanged himself; he died and was buried in the tomb of his father.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 17, 24, 'Then David came to Mahanaim, while Absalom crossed the Jordan with all the men of Israel.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 17, 25, 'Now Absalom had set Amasa over the army in the place of Joab. Amasa was the son of a man named Ithra the Ishmaelite, who had married Abigal daughter of Nahash, sister of Zeruiah, Joab"s mother.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 17, 26, 'The Israelites and Absalom encamped in the land of Gilead.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 17, 27, 'When David came to Mahanaim, Shobi son of Nahash from Rabbah of the Ammonites, and Machir son of Ammiel from Lo-debar, and Barzillai the Gileadite from Rogelim,', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 17, 28, 'brought beds, basins, and earthen vessels, wheat, barley, meal, parched grain, beans and lentils,', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 17, 29, 'honey and curds, sheep, and cheese from the herd, for David and the people with him to eat; for they said, "The troops are hungry and weary and thirsty in the wilderness."', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(10, '2 Sam', '2 Samuel', 18, 1, 'Then David mustered the men who were with him, and set over them commanders of thousands and commanders of hundreds.', 'en', 'NRSV-CE', 'The Defeat and Death of Absalom'),
(10, '2 Sam', '2 Samuel', 18, 2, 'And David divided the army into three groups: one third under the command of Joab, one third under the command of Abishai son of Zeruiah, Joab"s brother, and one third under the command of Ittai the Gittite. The king said to the men, "I myself will also go out with you."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 18, 3, 'But the men said, "You shall not go out. For if we flee, they will not care about us. If half of us die, they will not care about us. But you are worth ten thousand of us; therefore it is better that you send us help from the city."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 18, 4, 'The king said to them, "Whatever seems best to you I will do." So the king stood at the side of the gate, while all the army marched out by hundreds and by thousands.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 18, 5, 'The king ordered Joab and Abishai and Ittai, saying, "Deal gently for my sake with the young man Absalom." And all the people heard when the king gave orders to all the commanders concerning Absalom.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 18, 6, 'So the army went out into the field against Israel; and the battle was fought in the forest of Ephraim.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 18, 7, 'The men of Israel were defeated there by the servants of David, and the slaughter there was great on that day, twenty thousand men.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 18, 8, 'The battle spread over the face of all the country; and the forest claimed more victims that day than the sword.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 18, 9, 'Absalom happened to meet the servants of David. Absalom was riding on his mule, and the mule went under the thick branches of a great oak. His head caught fast in the oak, and he was left hanging between heaven and earth, while the mule that was under him went on.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 18, 10, 'A man saw it, and told Joab, "I saw Absalom hanging in an oak."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 18, 11, 'Joab said to the man who told him, "What, you saw him! Why then did you not strike him there to the ground? I would have been glad to give you ten pieces of silver and a belt."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 18, 12, 'But the man said to Joab, "Even if I felt in my hand the weight of a thousand pieces of silver, I would not raise my hand against the king"s son; for in our hearing the king commanded you and Abishai and Ittai, saying: For my sake protect the young man Absalom!', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 18, 13, 'On the other hand, if I had dealt treacherously against his life (and there is nothing hidden from the king), then you yourself would have stood aloof."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 18, 14, 'Joab said, "I will not waste time like this with you." He took three spears in his hand, and thrust them into the heart of Absalom, while he was still alive in the oak.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 18, 15, 'And ten young men, Joab"s armor-bearers, surrounded Absalom and struck him, and killed him.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 18, 16, 'Then Joab sounded the trumpet, and the troops came back from pursuing Israel, for Joab restrained the troops.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 18, 17, 'They took Absalom, threw him into a great pit in the forest, and raised over him a very great heap of stones. Meanwhile all the Israelites fled to their homes.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 18, 18, 'Now Absalom in his lifetime had taken and set up for himself a pillar that is in the King"s Valley, for he said, "I have no son to keep my name in remembrance"; he called the pillar by his own name. It is called Absalom"s Monument to this day.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 18, 19, 'Then Ahimaaz son of Zadok said, "Let me run, and carry tidings to the king that the LORD has delivered him from the power of his enemies."', 'en', 'NRSV-CE', 'David Hears of Absalom"s Death'),
(10, '2 Sam', '2 Samuel', 18, 20, 'Joab said to him, "You are not to carry tidings today; you may carry tidings another day, but today you shall not do so, because the king"s son is dead."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 18, 21, 'Then Joab said to a Cushite, "Go, tell the king what you have seen." The Cushite bowed before Joab, and ran.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 18, 22, 'Then Ahimaaz son of Zadok said again to Joab, "Come what may, let me also run after the Cushite." And Joab said, "Why will you run, my son, seeing that you have no reward for the tidings?"', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 18, 23, '"Come what may," he said, "I will run." So he said to him, "Run." Then Ahimaaz ran by the way of the Plain, and outran the Cushite.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 18, 24, 'Now David was sitting between the two gates. The sentinel went up to the roof of the gate by the wall, and when he looked up, he saw a man running alone.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 18, 25, 'The sentinel shouted and told the king. The king said, "If he is alone, there are tidings in his mouth." He kept coming, and drew near.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 18, 26, 'Then the sentinel saw another man running; and the sentinel called to the gatekeeper and said, "See, another man running alone!" The king said, "He also is bringing tidings."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 18, 27, 'The sentinel said, "I think the running of the first one is like the running of Ahimaaz son of Zadok." The king said, "He is a good man, and comes with good tidings."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 18, 28, 'Then Ahimaaz cried out to the king, "All is well!" He prostrated himself before the king with his face to the ground, and said, "Blessed be the LORD your God, who has delivered up the men who raised their hand against my lord the king."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 18, 29, 'The king said, "Is it well with the young man Absalom?" Ahimaaz answered, "When Joab sent your servant, I saw a great tumult, but I do not know what it was."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 18, 30, 'The king said, "Turn aside, and stand here." So he turned aside, and stood still.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 18, 31, 'Then the Cushite came; and the Cushite said, "Good tidings for my lord the king! For the LORD has vindicated you this day, delivering you from the power of all who rose up against you."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 18, 32, 'The king said to the Cushite, "Is it well with the young man Absalom?" The Cushite answered, "May the enemies of my lord the king, and all who rise up to do you harm, be like that young man."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 18, 33, 'The king was deeply moved, and went up to the chamber over the gate, and wept; and as he went, he said, "O my son Absalom, my son, my son Absalom! Would I had died instead of you, O Absalom, my son, my son!"', 'en', 'NRSV-CE', 'David Mourns for Absalom');
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(10, '2 Sam', '2 Samuel', 19, 1, 'It was told Joab, "The king is weeping and mourning for Absalom."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 19, 2, 'So the victory that day was turned into mourning for all the troops; for the troops heard that day, "The king is grieving for his son."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 19, 3, 'The troops stole into the city that day as soldiers steal in who are ashamed when they flee in battle.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 19, 4, 'The king covered his face, and the king cried with a loud voice, "O my son Absalom, O Absalom, my son, my son!"', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 19, 5, 'Then Joab came into the house to the king, and said, "Today you have covered with shame the faces of all your officers who have saved your life today, and the lives of your sons and your daughters, and the lives of your wives and your concubines,', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 19, 6, 'for love of those who hate you and for hatred of those who love you. You have made it clear today that commanders and officers are nothing to you; for I perceive that if Absalom were alive and all of us were dead today, then you would be pleased.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 19, 7, 'So go out at once and speak kindly to your servants; for I swear by the LORD, if you do not go, not a man will stay with you this night; and this will be worse for you than any disaster that has come upon you from your youth until now."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 19, 8, 'Then the king got up and took his seat in the gate. The troops were all told, "See, the king is sitting in the gate"; and all the troops came before the king.
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(10, '2 Sam', '2 Samuel', 20, 1, 'Now a scoundrel named Sheba son of Bichri, a Benjaminite, happened to be there. He sounded the trumpet and cried out,
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(10, '2 Sam', '2 Samuel', 21, 1, 'Now there was a famine in the days of David for three years, year after year; and David inquired of the LORD. The LORD said, "There is bloodguilt on Saul and on his house, because he put the Gibeonites to death."', 'en', 'NRSV-CE', 'David Avenges the Gibeonites'),
(10, '2 Sam', '2 Samuel', 21, 2, 'So the king called the Gibeonites and spoke to them. (Now the Gibeonites were not of the people of Israel, but of the remnant of the Amorites; although the people of Israel had sworn to spare them, Saul had tried to wipe them out in his zeal for the people of Israel and Judah.)', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 21, 3, 'David said to the Gibeonites, "What shall I do for you? How shall I make expiation, that you may bless the heritage of the LORD?"', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 21, 4, 'The Gibeonites said to him, "It is not a matter of silver or gold between us and Saul or his house; neither is it for us to put anyone to death in Israel." He said, "What do you say that I should do for you?"', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 21, 5, 'They said to the king, "The man who consumed us and planned to destroy us, so that we should have no place in all the territory of Israel--', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 21, 6, 'let seven of his sons be handed over to us, and we will impale them before the LORD at Gibeon on the mountain of the LORD." The king said, "I will hand them over."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 21, 7, 'But the king spared Mephibosheth, the son of Saul"s son Jonathan, because of the oath of the LORD that was between them, between David and Jonathan son of Saul.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 21, 8, 'The king took the two sons of Rizpah daughter of Aiah, whom she bore to Saul, Armoni and Mephibosheth; and the five sons of Merab daughter of Saul, whom she bore to Adriel son of Barzillai the Meholathite;', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 21, 9, 'he gave them into the hands of the Gibeonites, and they impaled them on the mountain before the LORD. The seven of them perished together. They were put to death in the first days of harvest, at the beginning of barley harvest.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 21, 10, 'Then Rizpah the daughter of Aiah took sackcloth, and spread it on a rock for herself, from the beginning of harvest until rain fell on them from the heavens; she did not allow the birds of the air to come on the bodies by day, or the wild animals by night.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 21, 11, 'When David was told what Rizpah daughter of Aiah, the concubine of Saul, had done,', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 21, 12, 'David went and took the bones of Saul and the bones of his son Jonathan from the people of Jabesh-gilead, who had stolen them from the public square of Beth-shan, where the Philistines had hung them up, on the day the Philistines killed Saul on Gilboa.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 21, 13, 'He brought up from there the bones of Saul and the bones of his son Jonathan; and they gathered the bones of those who had been impaled.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 21, 14, 'They buried the bones of Saul and of his son Jonathan in the land of Benjamin in Zela, in the tomb of his father Kish; they did all that the king commanded. After that, God heeded supplications for the land.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 21, 15, 'The Philistines went to war again with Israel, and David went down together with his servants. They fought against the Philistines, and David grew weary.', 'en', 'NRSV-CE', 'Exploits of David"s Men'),
(10, '2 Sam', '2 Samuel', 21, 16, 'Ishbi-benob, one of the descendants of the giants, whose spear weighed three hundred shekels of bronze, and who was fitted out with new weapons, said he would kill David.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 21, 17, 'But Abishai son of Zeruiah came to his aid, and attacked the Philistine and killed him. Then David"s men swore to him, "You shall not go out with us to battle any longer, so that you do not quench the lamp of Israel."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 21, 18, 'After this a battle took place with the Philistines, at Gob; then Sibbecai the Hushathite killed Saph, who was one of the descendants of the giants.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 21, 19, 'Then there was another battle with the Philistines at Gob; and Elhanan son of Jaare-oregim, the Bethlehemite, killed Goliath the Gittite, the shaft of whose spear was like a weaver"s beam.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 21, 20, 'There was again war at Gath, where there was a man of great size, who had six fingers on each hand, and six toes on each foot, twenty-four in number; he too was descended from the giants.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 21, 21, 'When he taunted Israel, Jonathan son of David"s brother Shimei, killed him.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 21, 22, 'These four were descended from the giants in Gath; they fell by the hands of David and his servants.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(10, '2 Sam', '2 Samuel', 22, 1, 'David spoke to the LORD the words of this song on the day when the LORD delivered him from the hand of all his enemies, and from the hand of Saul.', 'en', 'NRSV-CE', 'David"s Song of Thanksgiving'),
(10, '2 Sam', '2 Samuel', 22, 2, 'He said:
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(10, '2 Sam', '2 Samuel', 23, 1, 'Now these are the last words of David:
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(10, '2 Sam', '2 Samuel', 24, 1, 'Again the anger of the LORD was kindled against Israel, and he incited David against them, saying, "Go, count the people of Israel and Judah."', 'en', 'NRSV-CE', 'David"s Census of Israel and Judah'),
(10, '2 Sam', '2 Samuel', 24, 2, 'So the king said to Joab and the commanders of the army, who were with him, "Go through all the tribes of Israel, from Dan to Beer-sheba, and take a census of the people, so that I may know how many there are."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 24, 3, 'But Joab said to the king, "May the LORD your God increase the number of the people a hundredfold, while the eyes of my lord the king can still see it! But why does my lord the king want to do this?"', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 24, 4, 'But the king"s word prevailed against Joab and the commanders of the army. So Joab and the commanders of the army went out from the presence of the king to take a census of the people of Israel.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 24, 5, 'They crossed the Jordan, and began from Aroer and from the city that is in the middle of the valley, toward Gad and on to Jazer.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 24, 6, 'Then they came to Gilead, and to Kadesh in the land of the Hittites; and they came to Dan, and from Dan they went around to Sidon,', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 24, 7, 'and came to the fortress of Tyre and to all the cities of the Hivites and Canaanites; and they went out to the Negeb of Judah at Beer-sheba.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 24, 8, 'So when they had gone through all the land, they came back to Jerusalem at the end of nine months and twenty days.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 24, 9, 'Joab reported to the king the number of those who had been recorded: in Israel there were eight hundred thousand soldiers able to draw the sword, and those of Judah were five hundred thousand.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 24, 10, 'But afterward, David was stricken to the heart because he had numbered the people. David said to the LORD, "I have sinned greatly in what I have done. But now, O LORD, I pray you, take away the guilt of your servant; for I have done very foolishly."', 'en', 'NRSV-CE', 'Judgment on David"s Sin'),
(10, '2 Sam', '2 Samuel', 24, 11, 'When David rose in the morning, the word of the LORD came to the prophet Gad, David"s seer, saying,', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 24, 12, '"Go and say to David: Thus says the LORD: Three things I offer you; choose one of them, and I will do it to you."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 24, 13, 'So Gad came to David and told him; he asked him, "Shall three years of famine come to you on your land? Or will you flee three months before your foes while they pursue you? Or shall there be three days" pestilence in your land? Now consider, and decide what answer I shall return to the one who sent me."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 24, 14, 'Then David said to Gad, "I am in great distress; let us fall into the hand of the LORD, for his mercy is great; but let me not fall into human hands."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 24, 15, 'So the LORD sent a pestilence on Israel from that morning until the appointed time; and seventy thousand of the people died, from Dan to Beer-sheba.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 24, 16, 'But when the angel stretched out his hand toward Jerusalem to destroy it, the LORD relented concerning the evil, and said to the angel who was bringing destruction among the people, "It is enough; now stay your hand." The angel of the LORD was then by the threshing floor of Araunah the Jebusite.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 24, 17, 'When David saw the angel who was destroying the people, he said to the LORD, "I alone have sinned, and I alone have done wickedly; but these sheep, what have they done? Let your hand, I pray, be against me and against my father"s house."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 24, 18, 'That day Gad came to David and said to him, "Go up and erect an altar to the LORD on the threshing floor of Araunah the Jebusite."', 'en', 'NRSV-CE', 'David"s Altar on the Threshing Floor'),
(10, '2 Sam', '2 Samuel', 24, 19, 'Following Gad"s instructions, David went up, as the LORD had commanded.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 24, 20, 'When Araunah looked down, he saw the king and his servants coming toward him; and Araunah went out and prostrated himself before the king with his face to the ground.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 24, 21, 'Araunah said, "Why has my lord the king come to his servant?" David said, "To buy the threshing floor from you in order to build an altar to the LORD, so that the plague may be averted from the people."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 24, 22, 'Then Araunah said to David, "Let my lord the king take and offer up what seems good to him; here are the oxen for the burnt offering, and the threshing sledges and the yokes of the oxen for the wood.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 24, 23, 'All this, O king, Araunah gives to the king." And Araunah said to the king, "May the LORD your God respond favorably to you."', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 24, 24, 'But the king said to Araunah, "No, but I will buy them from you for a price; I will not offer burnt offerings to the LORD my God that cost me nothing." So David bought the threshing floor and the oxen for fifty shekels of silver.', 'en', 'NRSV-CE', NULL),
(10, '2 Sam', '2 Samuel', 24, 25, 'David built there an altar to the LORD, and offered burnt offerings and offerings of well-being. So the LORD answered his supplication for the land, and the plague was averted from Israel.', 'en', 'NRSV-CE', NULL);
